window.POLICIES=[{"id":"cn-national-024","title":"全国社会心理服务体系建设试点工作方案","issuer":"国家卫生健康委等10部门","doc_no":"国卫疾控发〔2018〕44号","publish_date":"2018-11-19","effective_date":"2018-11-19","level":"部门规范性文件","region":"中国·国家","category":"national","source_site":"ncmhc.org.cn","source_url":"https://ncmhc.org.cn/channel/newsinfo/6224","attachments":[],"summary":"请各省(区、市)卫生健康行政部门、政法委牵头，会同有关部门严格按照试点工作方案要求，高度重视试点工作，将社会心理服务体系建设试点作为推进平安中国、健康中国建设的重要抓手，做好试点地区遴选论证，加强对试点工作的组织领导，认真指导试点地区做好试点实施方案编制、启动培训、试点任务组织实施等工作，定期对试点地区进行督导，确保按期完成试点任务。","tags":["社会心理服务","试点","心理健康"],"language":"zh"},{"id":"cn-national-025","title":"严重精神障碍管理治疗工作规范（2018年版）","issuer":"国家卫生健康委","doc_no":"国卫疾控发〔2018〕13号","publish_date":"2018-05-28","effective_date":"2018-05-28","level":"部门规范性文件","region":"中国·国家","category":"national","source_site":"www.gov.cn","source_url":"https://www.gov.cn/gongbao/content/2018/content_5338247.htm","attachments":[],"summary":"卫生健康委关于印发严重精神障碍管理治疗工作规范（2018年版）的通知国卫疾控发〔2018〕13号各省、自治区、直辖市及新疆生产建设兵团卫生计生委：为贯彻落实《精神卫生法》、《全国精神卫生工作规划（2015-2020年）》，适应精神卫生工作发展需要，结合《国家基本公共卫生服务规范（第三版）》对严重精神障碍管理治疗工作的有关要求，我委组织编制了《严重精神障碍管理治疗工作规范（2018年版）》。","tags":["严重精神障碍","管理治疗","精神卫生"],"language":"zh"},{"id":"cn-national-001","title":"中华人民共和国精神卫生法","issuer":"全国人民代表大会常务委员会","doc_no":"主席令第62号","publish_date":"2018-04-27","effective_date":"2018-04-27","level":"法律","region":"中国·国家","category":"national","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=2c909fdd678bf17901678bf7448a066d","attachments":[],"summary":"第一条 为了发展精神卫生事业，规范精神卫生服务，维护精神障碍患者的合法权益，制定本法。第二条 在中华人民共和国境内开展维护和增进公民心理健康、预防和治疗精神障碍、促进精神障碍患者康复的活动，适用本法。第三条 精神卫生工作实行预防为主的方针，坚持预防、治疗和康复相结合的原则。第四条 精神障碍患者的人格尊严、人身和财产安全不受侵犯。","tags":["精神卫生","心理健康","权益保障"],"language":"zh"},{"id":"cn-national-023","title":"关于加强心理健康服务的指导意见","issuer":"国家卫生计生委等22部门","doc_no":"国卫疾控发〔2016〕77号","publish_date":"2016-12-30","effective_date":"2016-12-30","level":"部门规范性文件","region":"中国·国家","category":"national","source_site":"ncmhc.org.cn","source_url":"https://ncmhc.org.cn/channel/newsinfo/6264","attachments":[],"summary":"《关于加强心理健康服务的指导意见》由国家卫生计生委等22部门于2016年发布，属于部门规范性文件，主要涉及心理健康服务、社会心理服务体系、指导意见等内容。该文件为心理健康相关工作的政策依据之一，可用于了解相应层级在精神卫生服务、心理服务体系建设或重点人群心理健康促进方面的制度安排。","tags":["心理健康服务","社会心理服务体系","指导意见"],"language":"zh"},{"id":"cn-national-022","title":"全国精神卫生工作规划（2015—2020年）","issuer":"国务院办公厅","doc_no":"国办发〔2015〕44号","publish_date":"2015-06-04","effective_date":"2015-06-04","level":"行政法规","region":"中国·国家","category":"national","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/content/2015-06/18/content_9860.htm","attachments":[],"summary":"国务院办公厅关于转发卫生计生委等部门全国精神卫生工作规划（2015—2020年）的通知国办发〔2015〕44号各省、自治区、直辖市人民政府，国务院各部委、各直属机构：卫生计生委、中央综治办、发展改革委、教育部、公安部、民政部、司法部、财政部、人力资源社会保障部、中国残联《全国精神卫生工作规划（2015—2020年）》已经国务院同意，现转发给你们，请结合实际认真贯彻执行。","tags":["精神卫生","心理健康","工作规划"],"language":"zh"},{"id":"cn-national-012","title":"中华人民共和国传染病防治法","issuer":"全国人民代表大会常务委员会","doc_no":"","publish_date":"2025-04-30","effective_date":"2025-09-01","level":"法律","region":"中国·国家","category":"national","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff8081819667441b019686946a752bbd","attachments":[],"summary":"第一条 为了预防、控制和消除传染病的发生与流行，保障公众生命安全和身体健康，防范和化解公共卫生风险，维护国家安全和社会稳定，根据宪法，制定本法。文件围绕传染病、心理援助、公共卫生提出具体要求和实施举措，是心理健康相关法律法规与政策体系的重要组成部分。","tags":["传染病","心理援助","公共卫生"],"language":"zh"},{"id":"cn-national-010","title":"中华人民共和国突发事件应对法","issuer":"全国人民代表大会常务委员会","doc_no":"主席令第25号","publish_date":"2024-06-28","effective_date":"2024-11-01","level":"法律","region":"中国·国家","category":"national","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff8081818d6a424b01905f13edba2efb","attachments":[],"summary":"第一条 为了预防和减少突发事件的发生，控制、减轻和消除突发事件引起的严重社会危害，提高突发事件预防和应对能力，规范突发事件应对活动，保护人民生命财产安全，维护国家安全、公共安全、生态环境安全和社会秩序，根据宪法，制定本法。专业应急救援人员应当具备相应的身体条件、专业技能和心理素质，取得国家规定的应急救援职业资格，具体办法由国务院应急管理部门会同国务院有关部门制定。","tags":["突发事件","心理援助","危机干预"],"language":"zh"},{"id":"cn-national-003","title":"中华人民共和国未成年人保护法","issuer":"全国人民代表大会常务委员会","doc_no":"主席令第57号","publish_date":"2024-04-26","effective_date":"2024-04-26","level":"法律","region":"中国·国家","category":"national","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff8081818f197cf001905e567af635a0","attachments":[],"summary":"第一条 为了保护未成年人身心健康，保障未成年人合法权益，促进未成年人德智体美劳全面发展，培养有理想、有道德、有文化、有纪律的社会主义建设者和接班人，培养担当民族复兴大任的时代新人，根据宪法，制定本法。（二）关注未成年人的生理、心理状况和情感需求；与未成年人、被委托人至少每周联系和交流一次，了解未成年人的生活、学习、心理等情况，并给予未成年人亲情关爱。","tags":["未成年人","心理健康","权益保护"],"language":"zh"},{"id":"cn-national-006","title":"中华人民共和国妇女权益保障法","issuer":"全国人民代表大会","doc_no":"主席令第56号","publish_date":"2022-10-30","effective_date":"2023-01-01","level":"法律","region":"中国·国家","category":"national","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff808181841257210184281512de0eec","attachments":[],"summary":"第一条 为了保障妇女的合法权益，促进男女平等和妇女全面发展，充分发挥妇女在全面建设社会主义现代化国家中的作用，弘扬社会主义核心价值观，根据宪法，制定本法。第二十四条 学校应当根据女学生的年龄阶段，进行生理卫生、心理健康和自我保护教育，在教育、管理、设施等方面采取措施，提高其防范性侵害、性骚扰的自我保护意识和能力，保障女学生的人身安全和身心健康发展。","tags":["妇女权益","心理健康","权益保障"],"language":"zh"},{"id":"cn-national-017","title":"“十四五”国民健康规划","issuer":"国务院办公厅","doc_no":"国办发〔2022〕11号","publish_date":"2022-04-27","effective_date":"2022-04-27","level":"行政法规","region":"中国·国家","category":"national","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/content/2022-05/20/content_5691424.htm","attachments":[],"summary":"国务院办公厅关于印发“十四五”国民健康规划的通知国办发〔2022〕11号各省、自治区、直辖市人民政府，国务院各部委、各直属机构：《“十四五”国民健康规划》已经国务院同意，现印发给你们，请认真贯彻执行。慢性病发病率上升且呈年轻化趋势，患有常见精神障碍和心理行为问题人数逐年增多，食品安全、环境卫生、职业健康等问题仍较突出。","tags":["国民健康","心理健康","五年规划"],"language":"zh"},{"id":"cn-national-014","title":"最高人民法院关于审理人身损害赔偿案件适用法律若干问题的解释","issuer":"最高人民法院","doc_no":"法释〔2003〕20号","publish_date":"2022-04-24","effective_date":"2022-05-01","level":"司法解释","region":"中国·国家","category":"national","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff80818181d823c50181ffd1b39b5e54","attachments":[],"summary":"最高人民法院关于审理人身损害赔偿案件适用法律若干问题的解释为正确审理人身损害赔偿案件，依法保护当事人的合法权益，根据《中华人民共和国民法典》《中华人民共和国民事诉讼法》等有关法律规定，结合审判实践，制定本解释。第一条 因生命、身体、健康遭受侵害，赔偿权利人起诉请求赔偿义务人赔偿物质损害和精神损害的，人民法院应予受理。","tags":["人身损害","精神损害","司法保护"],"language":"zh"},{"id":"cn-national-021","title":"国家残疾预防行动计划（2021—2025年）","issuer":"国务院办公厅","doc_no":"国办发〔2021〕50号","publish_date":"2021-12-14","effective_date":"2021-12-14","level":"行政法规","region":"中国·国家","category":"national","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/content/2022-01/05/content_5666521.htm","attachments":[],"summary":"国务院办公厅关于印发国家残疾预防行动计划（2021—2025年）的通知国办发〔2021〕50号各省、自治区、直辖市人民政府，国务院各部委、各直属机构：《国家残疾预防行动计划（2021—2025年）》已经国务院同意，现印发给你们，请认真贯彻执行。（国家卫生健康委、国家疾控局牵头，教育部、体育总局、中国残联按职责分工负责）加强社会心理服务和精神疾病防治。","tags":["残疾预防","心理健康","行动计划"],"language":"zh"},{"id":"cn-national-004","title":"中华人民共和国家庭教育促进法","issuer":"全国人民代表大会常务委员会","doc_no":"主席令第98号","publish_date":"2021-10-23","effective_date":"2022-01-01","level":"法律","region":"中国·国家","category":"national","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff8081817cac3b2d017cac5a6c6f0109","attachments":[],"summary":"第一条 为了发扬中华民族重视家庭教育的优良传统，引导全社会注重家庭、家教、家风，增进家庭幸福与社会和谐，培养德智体美劳全面发展的社会主义建设者和接班人，制定本法。县级以上精神文明建设部门和县级以上人民政府公安、民政、司法行政、人力资源和社会保障、文化和旅游、卫生健康、市场监督管理、广播电视、体育、新闻出版、网信等有关部门在各自的职责范围内做好家庭教育工作。","tags":["家庭教育","心理健康","未成年人"],"language":"zh"},{"id":"cn-national-018","title":"中国儿童发展纲要（2021—2030年）","issuer":"国务院","doc_no":"国发〔2021〕16号","publish_date":"2021-09-08","effective_date":"2021-09-08","level":"行政法规","region":"中国·国家","category":"national","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/content/2021-09/27/content_5639412.htm","attachments":[],"summary":"国务院关于印发中国妇女发展纲要和中国儿童发展纲要的通知国发〔2021〕16号各省、自治区、直辖市人民政府，国务院各部委、各直属机构：现将《中国妇女发展纲要（2021—2030年）》和《中国儿童发展纲要（2021—2030年）》印发给你们，请认真贯彻执行。6．妇女心理健康素养水平不断提升。","tags":["儿童发展","心理健康","权益保护"],"language":"zh"},{"id":"cn-national-020","title":"“十四五”残疾人保障和发展规划","issuer":"国务院","doc_no":"国发〔2021〕10号","publish_date":"2021-07-08","effective_date":"2021-07-08","level":"行政法规","region":"中国·国家","category":"national","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/content/2021-07/21/content_5626391.htm","attachments":[],"summary":"国务院关于印发“十四五”残疾人保障和发展规划的通知国发〔2021〕10号各省、自治区、直辖市人民政府，国务院各部委、各直属机构：现将《“十四五”残疾人保障和发展规划》印发给你们，请认真贯彻执行。发挥政府主导作用和社会力量、市场主体协同作用，发挥地方优势和基层首创精神，集成政策、整合资源、优化服务，促进残疾人事业与经济社会协调发展，推动城乡、区域残疾人事业均衡发展。","tags":["残疾人","康复","心理健康"],"language":"zh"},{"id":"cn-national-008","title":"中华人民共和国预防未成年人犯罪法","issuer":"全国人民代表大会常务委员会","doc_no":"主席令第64号","publish_date":"2020-12-26","effective_date":"2021-06-01","level":"法律","region":"中国·国家","category":"national","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff80808175265dd40176a88c218f2853","attachments":[],"summary":"第一条 为了保障未成年人身心健康，培养未成年人良好品行，有效预防未成年人违法犯罪，制定本法。第十二条 预防未成年人犯罪，应当结合未成年人不同年龄的生理、心理特点，加强青春期教育、心理关爱、心理矫治和预防犯罪对策的研究。发现未成年人心理或者行为异常的，应当及时了解情况并进行教育、引导和劝诫，不得拒绝或者怠于履行监护职责。","tags":["未成年人","心理矫治","犯罪预防"],"language":"zh"},{"id":"cn-national-002","title":"中华人民共和国基本医疗卫生与健康促进法","issuer":"全国人民代表大会常务委员会","doc_no":"主席令第38号","publish_date":"2019-12-28","effective_date":"2020-06-01","level":"法律","region":"中国·国家","category":"national","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff80808171e9e18101727e38094d7e07","attachments":[],"summary":"第一条 为了发展医疗卫生与健康事业，保障公民享有基本医疗卫生服务，提高公民健康水平，推进健康中国建设，根据宪法，制定本法。第十九条 国家建立健全突发事件卫生应急体系，制定和完善应急预案，组织开展突发事件的医疗救治、卫生学调查处置和心理援助等卫生应急工作，有效控制和消除危害。第二十八条 国家发展精神卫生事业，建设完善精神卫生服务体系，维护和增进公民心理健康，预防、治疗精神障碍。","tags":["健康促进","心理健康","基本医疗卫生"],"language":"zh"},{"id":"cn-national-009","title":"中华人民共和国社区矫正法","issuer":"全国人民代表大会常务委员会","doc_no":"主席令第40号","publish_date":"2019-12-28","effective_date":"2020-07-01","level":"法律","region":"中国·国家","category":"national","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff80808171e9e18101727e4443b37e86","attachments":[],"summary":"第一条 为了推进和规范社区矫正工作，保障刑事判决、刑事裁定和暂予监外执行决定的正确执行，提高教育矫正质量，促进社区矫正对象顺利融入社会，预防和减少犯罪，根据宪法，制定本法。第十一条 社区矫正机构根据需要，组织具有法律、教育、心理、社会工作等专业知识或者实践经验的社会工作者开展社区矫正相关工作。","tags":["社区矫正","心理矫治","心理健康"],"language":"zh"},{"id":"cn-national-015","title":"国务院关于实施健康中国行动的意见","issuer":"国务院","doc_no":"国发〔2019〕13号","publish_date":"2019-07-15","effective_date":"2019-07-15","level":"行政法规","region":"中国·国家","category":"national","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/content/2019-07/15/content_5409492.htm","attachments":[],"summary":"国发〔2019〕13号各省、自治区、直辖市人民政府，国务院各部委、各直属机构:人民健康是民族昌盛和国家富强的重要标志，预防是最经济最有效的健康策略。肝炎、结核病、艾滋病等重大传染病防控形势仍然严峻，精神卫生、职业健康、地方病等方面问题不容忽视。心理健康是健康的重要组成部分。通过心理健康教育、咨询、治疗、危机干预等方式，引导公众科学缓解压力，正确认识和应对常见精神障碍及心理行为问题。","tags":["健康中国行动","心理健康促进行动","健康政策"],"language":"zh"},{"id":"cn-national-007","title":"中华人民共和国老年人权益保障法","issuer":"全国人民代表大会常务委员会","doc_no":"主席令第73号","publish_date":"2018-12-29","effective_date":"2018-12-29","level":"法律","region":"中国·国家","category":"national","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff8080816f135f46016f20f4bf851746","attachments":[],"summary":"第一条 为了保障老年人合法权益，发展老龄事业，弘扬中华民族敬老、养老、助老的美德，根据宪法，制定本法。第十四条 赡养人应当履行对老年人经济上供养、生活上照料和精神上慰藉的义务，照顾老年人的特殊需要。第十八条 家庭成员应当关心老年人的精神需求，不得忽视、冷落老年人。第七十二条 国家和社会采取措施，开展适合老年人的群众性文化、体育、娱乐活动，丰富老年人的精神文化生活。","tags":["老年人","心理健康","权益保障"],"language":"zh"},{"id":"cn-national-005","title":"中华人民共和国残疾人保障法","issuer":"全国人民代表大会常务委员会","doc_no":"主席令第36号","publish_date":"2018-10-26","effective_date":"2018-10-26","level":"法律","region":"中国·国家","category":"national","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff8080816f135f46016f1d134c88132b","attachments":[],"summary":"第一条 为了维护残疾人的合法权益，发展残疾人事业，保障残疾人平等地充分参与社会生活，共享社会物质文化成果，根据宪法，制定本法。第二条 残疾人是指在心理、生理、人体结构上，某种组织、功能丧失或者不正常，全部或者部分丧失以正常方式从事某种活动能力的人。残疾人包括视力残疾、听力残疾、言语残疾、肢体残疾、智力残疾、精神残疾、多重残疾和其他残疾的人。","tags":["残疾人","康复","心理健康"],"language":"zh"},{"id":"cn-national-013","title":"残疾预防和残疾人康复条例","issuer":"国务院","doc_no":"国务院令第675号","publish_date":"2018-09-18","effective_date":"2017-07-01","level":"行政法规","region":"中国·国家","category":"national","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff8080816f3cbb3c016f413166981c2e","attachments":[],"summary":"第一条 为了预防残疾的发生、减轻残疾程度，帮助残疾人恢复或者补偿功能，促进残疾人平等、充分地参与社会生活，发展残疾预防和残疾人康复事业，根据《中华人民共和国残疾人保障法》，制定本条例。第二条 本条例所称残疾预防，是指针对各种致残因素，采取有效措施，避免个人心理、生理、人体结构上某种组织、功能的丧失或者异常，防止全部或者部分丧失正常参与社会活动的能力。","tags":["残疾预防","康复","心理健康"],"language":"zh"},{"id":"cn-national-016","title":"“健康中国2030”规划纲要","issuer":"中共中央、国务院","doc_no":"","publish_date":"2016-10-25","effective_date":"2016-10-25","level":"行政法规","region":"中国·国家","category":"national","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/2016-10/25/content_5124174.htm","attachments":[],"summary":"中共中央 国务院印发《“健康中国2030”规划纲要》2016-10-25 19:49新华社北京10月25日电 近日，中共中央、国务院印发了《“健康中国2030”规划纲要》，并发出通知，要求各地区各部门结合实际认真贯彻落实。加强精神文明建设，发展健康文化，移风易俗，培育良好的生活习惯。","tags":["健康中国","心理健康","规划纲要"],"language":"zh"},{"id":"cn-national-011","title":"中华人民共和国禁毒法","issuer":"全国人民代表大会常务委员会","doc_no":"主席令第79号","publish_date":"2007-12-29","effective_date":"2008-06-01","level":"法律","region":"中国·国家","category":"national","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=2c909fdd678bf17901678bf64d550393","attachments":[],"summary":"第一条 为了预防和惩治毒品违法犯罪行为，保护公民身心健康，维护社会秩序，制定本法。第二条 本法所称毒品，是指鸦片、海洛因、甲基苯丙胺（冰毒）、吗啡、大麻、可卡因，以及国家规定管制的其他能够使人形成瘾癖的麻醉药品和精神药品。根据医疗、教学、科研的需要，依法可以生产、经营、使用、储存、运输麻醉药品和精神药品。","tags":["禁毒","心理治疗","康复"],"language":"zh"},{"id":"cn-national-019","title":"学校卫生工作条例","issuer":"国务院","doc_no":"国家教育委员会令第10号、卫生部令第1号","publish_date":"1990-06-04","effective_date":"1990-06-04","level":"行政法规","region":"中国·国家","category":"national","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff8080816f3cbb3c016f4088a7d903ea","attachments":[],"summary":"第一条 为加强学校卫生工作，提高学生的健康水平，制定本条例。学校对残疾、体弱学生，应当加强医学照顾和心理卫生工作。该文件围绕学校卫生、心理健康教育、学生健康等方面提出具体要求和工作举措，明确了相关责任主体与实施路径，是心理健康相关法律法规与政策体系的重要组成部分。","tags":["学校卫生","心理健康教育","学生健康"],"language":"zh"},{"id":"cn-ministry-016","title":"关于印发健全社会心理服务体系和危机干预机制实施方案的通知","issuer":"国家卫生健康委等25部门","doc_no":"","publish_date":"2026-04-09","effective_date":"2026-04-09","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/202604/content_7065035.htm","attachments":[],"summary":"一、总体要求以习近平新时代中国特色社会主义思想为指导，贯彻落实党的二十大和二十届历次全会精神，强化部门协作和社会参与，将心理服务融入社会治理体系及平安中国、健康中国建设，打造共建共治共享的社会心理服务新格局，推动形成自尊自信、理性平和、积极向上的社会心态。到2030年，覆盖全人群、全生命周期的社会心理服务体系和危机干预机制基本健全。","tags":["社会心理服务","危机干预","心理健康"],"language":"zh"},{"id":"cn-ministry-001","title":"教育部办公厅关于印发《进一步加强中小学生心理健康工作十条措施》的通知","issuer":"教育部办公厅","doc_no":"","publish_date":"2025-10-24","effective_date":"2025-10-24","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/202510/content_7045528.htm","attachments":[],"summary":"教育部办公厅2025年10月9日进一步加强中小学生心理健康工作十条措施为落实健康第一教育理念，进一步提高中小学生心理健康工作水平，针对中小学生心理健康阶段性特点和突出问题，制定以下工作措施。全面落实生命安全与健康教育进中小学课程教材指南，每月至少开展一次综合性教育实践活动，加强学生生命教育、青春期教育和挫折教育，提升学生适应环境、调适情绪、应对压力等方面能力，增强心理韧性和心理免疫力。","tags":["学生心理健康","十条措施","中小学"],"language":"zh"},{"id":"cn-ministry-022","title":"关于开展“儿科和精神卫生服务年”行动（2025-2027年）的通知","issuer":"国家卫生健康委、国家中医药局、国家疾控局","doc_no":"","publish_date":"2025-04-28","effective_date":"2025-04-28","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/202504/content_7021393.htm","attachments":[],"summary":"现将《“儿科和精神卫生服务年”行动方案（2025-2027年）》印发给你们，请认真组织实施，确保取得实效。一、工作目标通过开展“儿科和精神卫生服务年”行动，进一步提高儿科、心理健康和精神卫生服务可及性，增强群众获得感。精神专科医院以及规模较大的相关医疗机构普遍开设心理门诊、睡眠门诊等，医务人员普遍关注患者心理健康和精神卫生问题。","tags":["儿科","精神卫生","服务年"],"language":"zh"},{"id":"cn-ministry-023","title":"关于开展医疗机构医师附条件注册精神卫生专业执业范围有关工作的通知","issuer":"国家卫生健康委办公厅、国家中医药局综合司","doc_no":"","publish_date":"2025-04-02","effective_date":"2025-04-02","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/202504/content_7017017.htm","attachments":[],"summary":"现将有关要求通知如下：一、医师条件附条件注册精神卫生专业执业范围的医师应当同时满足以下条件：（一）临床或中医（包含中医、中西医结合和少数民族医）类别执业医师；（三）满足以下条件之一：1.临床类别医师符合《国家卫生计生委办公厅关于精神科从业医师注册有关事项的通知》（国卫办医函〔2014〕605号）中第一项条件的。","tags":["精神卫生","医师注册","人才队伍"],"language":"zh"},{"id":"cn-ministry-010","title":"国家卫生健康委关于应用“12356”全国统一心理援助热线电话号码的通知","issuer":"国家卫生健康委","doc_no":"","publish_date":"2024-12-25","effective_date":"2024-12-25","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/202412/content_6994470.htm","attachments":[],"summary":"一、各地卫生健康行政部门要积极协调地方通信管理局和电信、移动、联通、广电等电信运营商，对辖区内卫生健康行政部门主管的现有心理援助热线号码进行调整，力争在2025年春节或元旦前后投入运行，确保于2025年5月1日0时前，实现拨打“12356”电话号码接通心理援助热线的功能。积极推进心理援助与110、119、120等服务热线和综治维稳工作等建立联动机制，提升心理援助效能。","tags":["心理援助热线","12356","心理健康服务"],"language":"zh"},{"id":"cn-ministry-017","title":"教育部办公厅关于开展首个全国学生心理健康宣传教育月活动的通知","issuer":"教育部办公厅","doc_no":"","publish_date":"2024-05-14","effective_date":"2024-05-14","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/202405/content_6950862.htm","attachments":[],"summary":"一、活动主题全社会都行动起来，共促学生心理健康。三、活动安排（一）全面落实五育并举促进心理健康理念。（二）面向全体师生开展富有针对性的心理健康教育。各地教育行政部门和学校要加强教师培训，帮助各科教师学习掌握心理学知识，在学科教学中注重维护学生心理健康，促进学生身心健康、全面发展。","tags":["学生心理健康","宣传教育","心理健康月"],"language":"zh"},{"id":"cn-ministry-012","title":"民政部 国家卫生健康委 中国残联关于印发《精神障碍社区康复服务资源共享与转介管理办法》的通知","issuer":"民政部、国家卫生健康委、中国残联","doc_no":"","publish_date":"2023-12-30","effective_date":"2023-12-30","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/202312/content_6923518.htm","attachments":[],"summary":"第二条 精神障碍社区康复资源共享与转介服务（以下简称“精康转介服务”）工作纳入县级以上人民政府精神障碍社区康复服务工作领导小组或者部门协调工作机制，由民政部门牵头，卫生健康部门和残联等部门（单位）共同实施。第六条 具有精神障碍诊疗资质的医疗卫生机构负责对精神障碍患者开展出院康复评估、门诊就诊诊断评估，提供社区康复建议。","tags":["精神障碍","社区康复","转介服务"],"language":"zh"},{"id":"cn-ministry-002","title":"关于加强困境儿童心理健康关爱服务工作的指导意见","issuer":"民政部、教育部、国家卫生健康委、共青团中央、全国妇联","doc_no":"","publish_date":"2023-11-03","effective_date":"2023-11-03","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/202311/content_6913516.htm","attachments":[],"summary":"但是，一些困境儿童由于受成长环境等多重因素影响，面临心理健康问题，其中，一些留守儿童、流动儿童，由于缺乏陪伴或难以适应流入地生活等原因，更容易出现心理健康问题，迫切需要加强关心关爱。为进一步做好困境儿童心理健康关爱服务工作，现提出如下意见。二、主要内容（一）加强心理健康教育。鼓励学校为有需求的困境儿童选配有爱心有经验的心理教师或思政课教师作为成长导师，安排品学兼优的学生结为互助伙伴。","tags":["困境儿童","心理健康","关爱服务"],"language":"zh"},{"id":"cn-ministry-018","title":"教育部等十七部门关于印发《全面加强和改进新时代学生心理健康工作专项行动计划（2023—2025年）》的通知","issuer":"教育部等17部门","doc_no":"","publish_date":"2023-05-12","effective_date":"2023-05-12","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/202305/content_6857361.htm","attachments":[],"summary":"教育部 最高人民检察院 中央宣传部中央网信办 科技部 公安部民政部 财政部 国家卫生健康委广电总局 体育总局 中国科学院国务院妇儿工委办公室 共青团中央 全国妇联中国关心下一代工作委员会 中国科学技术协会2023年4月20日全面加强和改进新时代学生心理健康工作专项行动计划（2023—2025年）促进学生身心健康、全面发展，是党中央关心、人民群众关切、社会关注的重大课题。","tags":["学生心理健康","专项行动","五育并举"],"language":"zh"},{"id":"cn-ministry-024","title":"国家卫生健康委办公厅关于开展2022年世界精神卫生日宣传活动的通知","issuer":"国家卫生健康委办公厅","doc_no":"","publish_date":"2022-09-29","effective_date":"2022-09-29","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2022-09/29/content_5713623.htm","attachments":[],"summary":"为进一步加大心理健康和精神卫生工作宣传力度，提高公众认识，推动全社会重视、理解、支持相关工作，形成共同推进心理健康和精神卫生工作的良好局面，我委决定围绕2022年10月10日世界精神卫生日开展宣传活动。各地卫生健康行政部门要加强心理健康和精神卫生工作相关法律法规、政策要求、制度规范的宣传和培训工作，提高公众政策的知晓率，方便获取心理健康和精神卫生相关服务，推动维护和保障精神障碍患者合法权益。","tags":["世界精神卫生日","心理健康","科普宣传"],"language":"zh"},{"id":"cn-ministry-034","title":"民政部办公厅关于印发精神卫生福利机构新冠肺炎疫情防控指南（第五版）的通知","issuer":"民政部办公厅","doc_no":"","publish_date":"2022-09-25","effective_date":"2022-09-25","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2022-09/25/content_5711809.htm","attachments":[],"summary":"精神卫生福利机构人员密集，一旦有感染者传入极易造成聚集性疫情，发生重症风险高，疫情处置难度大。精神卫生福利机构所在地发生本土疫情后，应在第一时间启动相应防控措施，报请同级联防联控机制同意，对本行政区域内动态适用精神卫生福利机构两个防控指南直接作出整体部署，做到精准防控，最大程度保护机构内服务对象的生命安全和身体健康。","tags":["精神卫生","福利机构","疫情防控"],"language":"zh"},{"id":"cn-ministry-019","title":"教育部办公厅关于加强学生心理健康管理工作的通知","issuer":"教育部办公厅","doc_no":"","publish_date":"2021-07-24","effective_date":"2021-07-24","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2021-07/24/content_5627089.htm","attachments":[],"summary":"一、加强源头管理，全方位提升学生心理健康素养1.加强心理健康课程建设。发挥课堂教学主渠道作用，帮助学生掌握心理健康知识和技能，树立自助互助求助意识，学会理性面对挫折和困难。高校要面向本专科生开设心理健康公共必修课，原则上应设置2个学分（32—36学时），有条件的高校可开设更具针对性的心理健康选修课。","tags":["学生心理健康","监测预警","学校管理"],"language":"zh"},{"id":"cn-ministry-014","title":"关于印发全国社会心理服务体系建设试点2021年重点工作任务的通知","issuer":"国家卫生健康委办公厅、中央政法委办公厅","doc_no":"","publish_date":"2021-03-22","effective_date":"2021-03-22","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2021-03/22/content_5594964.htm","attachments":[],"summary":"浙江省嘉兴市创新地校合作，形成辐射全市的心理服务队伍；创新服务机制，推出“嘉心在线”公益互动心理服务平台，将“健心客厅”嵌入城乡图书馆，让群众更加方便地接受“面对面”心理服务。河南省驻马店市以“六进”“六服务”“六严控”“六结合”为抓手，将心理服务融入基层治理，推动形成理性平和的社会心态，有效化解社会矛盾。","tags":["社会心理服务","试点","重点工作"],"language":"zh"},{"id":"cn-ministry-011","title":"国家卫生健康委办公厅关于印发心理援助热线技术指南（试行）的通知","issuer":"国家卫生健康委办公厅","doc_no":"","publish_date":"2021-01-17","effective_date":"2021-01-17","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2021-01/17/content_5580529.htm","attachments":[],"summary":"为指导各地进一步加强和规范心理援助热线建设，推动全国热线服务高质量发展，我委组织制定了《心理援助热线技术指南（试行）》。国家卫生健康委办公厅2021年1月8日（信息公开形式：主动公开）心理援助热线技术指南（试行）心理援助热线（以下简称热线）具有及时性、匿名性、自控性、经济性、方便性等优势，能够不受时间和地域限制，随时为公众提供帮助。","tags":["心理援助热线","技术指南","危机干预"],"language":"zh"},{"id":"cn-ministry-013","title":"民政部 国家卫生健康委 中国残联关于印发《精神障碍社区康复服务工作规范》的通知","issuer":"民政部、国家卫生健康委、中国残联","doc_no":"","publish_date":"2020-12-29","effective_date":"2020-12-29","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2020-12/29/content_5650065.htm","attachments":[],"summary":"标 题：发文机关：民政部 卫生健康委 中国残疾人联合会发文字号：民发〔2020〕147号来 源：民政部网站主题分类：民政、扶贫、救灾\\其他公文种类：成文日期：2020年12月28日标 题：发文机关：民政部 卫生健康委 中国残疾人联合会发文字号：民发〔2020〕147号来 源：民政部网站主题分类：民政、扶贫、救灾\\其他公文种类：通知成文日期：2020年12月28日民发〔2020〕。","tags":["精神障碍","社区康复","工作规范"],"language":"zh"},{"id":"cn-ministry-029","title":"精神障碍诊疗规范","issuer":"国家卫生健康委办公厅","doc_no":"","publish_date":"2020-12-07","effective_date":"2020-12-07","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"ncmhc.org.cn","source_url":"https://ncmhc.org.cn/channel/newsinfo/6339","attachments":[],"summary":"《精神障碍诊疗规范》由国家卫生健康委办公厅于2020年发布，属于部门规范性文件，主要涉及精神障碍、诊疗规范、临床指南等内容。该文件为心理健康相关工作的政策依据之一，可用于了解相应层级在精神卫生服务、心理服务体系建设或重点人群心理健康促进方面的制度安排。","tags":["精神障碍","诊疗规范","临床指南"],"language":"zh"},{"id":"cn-ministry-006","title":"国家卫生健康委办公厅关于探索开展抑郁症、老年痴呆防治特色服务工作的通知","issuer":"国家卫生健康委办公厅","doc_no":"","publish_date":"2020-09-11","effective_date":"2020-09-11","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2020-09/11/content_5542555.htm","attachments":[],"summary":"请你单位组织辖区社会心理服务体系建设试点地区，将防治抑郁症、老年痴呆作为试点特色项目，按照方案要求做好组织实施。一、工作目标到2022年，在试点地区初步形成全民关注精神健康，支持和参与抑郁症防治工作的社会氛围。非精神专科医院的医师对抑郁症的识别率在现有基础上提升50％，规范治疗率在现有基础上提升20%。","tags":["抑郁症","老年痴呆","防治服务"],"language":"zh"},{"id":"cn-ministry-015","title":"关于印发全国社会心理服务体系建设试点2020年重点工作任务及增设试点的通知","issuer":"国家卫生健康委办公厅、中央政法委办公厅","doc_no":"","publish_date":"2020-04-28","effective_date":"2020-04-28","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2020-04/28/content_5507156.htm","attachments":[],"summary":"2019年1月，多部门联合启动社会心理服务体系建设试点（以下简称试点）工作。根据试点工作目标和2019年试点任务执行情况，结合应对新冠肺炎疫情防控需要，研究制定了全国社会心理服务体系建设试点2020年重点工作任务（见附件1），同时增设湖北省武汉市为全国社会心理服务体系建设试点地区（见附件2）。","tags":["社会心理服务","试点","重点工作"],"language":"zh"},{"id":"cn-ministry-020","title":"关于印发入境人员心理疏导和社会工作服务方案的通知","issuer":"国家卫生健康委、民政部等","doc_no":"","publish_date":"2020-04-22","effective_date":"2020-04-22","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2020-04/22/content_5505036.htm","attachments":[],"summary":"国家卫生健康委办公厅 民政部办公厅交通运输部办公厅 海关总署办公厅国家移民管理局综合司 民航局综合司国铁集团办公厅2020年4月21日（信息公开形式：主动公开）入境人员心理疏导和社会工作服务方案出入境口岸是新冠肺炎“外防输入”的重要关口。在防控新冠肺炎境外输入工作中，为做好入境人员心理疏导和社会工作服务，帮助入境人员适应隔离环境，提升入境管理和服务水平，特制定本方案。","tags":["入境人员","心理疏导","社会工作"],"language":"zh"},{"id":"cn-ministry-033","title":"民政部办公厅关于印发《民政精神卫生福利机构疫情防控工作指南（第二版）》的通知","issuer":"民政部办公厅","doc_no":"","publish_date":"2020-03-09","effective_date":"2020-03-09","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2020-03/09/content_5489058.htm","attachments":[],"summary":"同时担负医疗救治、流浪精神病人收治职责的精神卫生福利机构，应当按照其他规范要求统筹建立疫情防控工作机制。湖北省以及疫情严重地区的机构实施封闭式管理，暂停接收新的社会精神障碍患者入院，暂停探访、咨询、接待活动，做好暂不接收患者家属的安抚和政策解释工作。疫情低中度风险地区可按照当地疫情防控统一部署，在严格落实各项防护措施的前提下，逐步恢复接收新的社会精神障碍患者入院，有序开展相关活动和服务。","tags":["精神卫生","福利机构","疫情防控"],"language":"zh"},{"id":"cn-ministry-021","title":"关于加强应对新冠肺炎疫情工作中心理援助与社会工作服务的通知","issuer":"国家卫生健康委、民政部","doc_no":"","publish_date":"2020-03-07","effective_date":"2020-03-07","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2020-03/07/content_5488257.htm","attachments":[],"summary":"国家卫生健康委员会发文字号：国卫办疾控函〔2020〕194号来 源：卫生健康委网站主题分类：卫生、体育\\其他公文种类：成文日期：2020年03月05日标 题：发文机关：民政部;一、加强新冠肺炎感染者心理援助与社会工作服务湖北省武汉市等受疫情影响严重地区，要将心理援助与社会工作服务纳入疫情防控的整体部署，统筹安排，统一管理，在定点医院、方舱医院组织开展心理援助与社会工作服务。","tags":["疫情","心理援助","社会工作"],"language":"zh"},{"id":"cn-ministry-028","title":"儿童青少年心理健康行动方案","issuer":"国家卫生健康委等12部门","doc_no":"","publish_date":"2019-12-18","effective_date":"2019-12-18","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.moe.gov.cn","source_url":"http://www.moe.gov.cn/jyb_xxgk/moe_1777/moe_1779/202007/t20200728_475479.html","attachments":[],"summary":"国家卫生健康委 中宣部中央文明办 中央网信办教育部 民政部财政部 国家广电总局国务院妇儿工委办公室 共青团中央全国妇联 中国关工委2019年12月18日健康中国行动——儿童青少年心理健康行动方案（2019—2022年）儿童青少年心理健康工作是健康中国建设的重要内容。随着我国经济社会快速发展，儿童青少年心理行为问题发生率和精神障碍患病率逐渐上升，已成为关系国家和民族未来的重要公共卫生问题。","tags":["儿童青少年","心理健康","行动方案"],"language":"zh"},{"id":"cn-ministry-025","title":"中共教育部党组关于印发《高等学校学生心理健康教育指导纲要》的通知","issuer":"中共教育部党组","doc_no":"","publish_date":"2018-07-04","effective_date":"2018-07-04","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2018-12/31/content_5443423.htm","attachments":[],"summary":"中共教育部党组2018年7月4日高等学校学生心理健康教育指导纲要心理健康教育是提高大学生心理素质、促进其身心健康和谐发展的教育，是高校人才培养体系的重要组成部分，也是高校思想政治工作的重要内容。二、总体目标教育教学、实践活动、咨询服务、预防干预“四位一体”的心理健康教育工作格局基本形成。","tags":["高校","学生心理健康","教育纲要"],"language":"zh"},{"id":"cn-ministry-027","title":"中小学心理健康教育指导纲要","issuer":"教育部","doc_no":"","publish_date":"2012-12-07","effective_date":"2012-12-07","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.moe.gov.cn","source_url":"http://www.moe.gov.cn/srcsite/A06/s3325/201212/t20121211_145679.html","attachments":[],"summary":"登录 | 注册个人登录法人登录个人注册法人注册信息名称：教育部关于印发《中小学心理健康教育指导纲要（2012年修订）》的通知信息索引：360A06-05-2012-0024-1生成日期：2012-12-11发文机构：发文字号：教基一〔2012〕15号信息类别：基础教育内容概述：2002年，我部印发了《中小学心理健康教育指导纲要》，对各地中小学开展心理健康教育起到了指导和推动作用。","tags":["中小学","心理健康教育","指导纲要"],"language":"zh"},{"id":"cn-ministry-004","title":"关于印发《可能影响未成年人身心健康的网络信息分类办法》的通知","issuer":"国家网信办等","doc_no":"","publish_date":"2026-01-23","effective_date":"2026-01-23","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/202601/content_7055963.htm","attachments":[],"summary":"标 题：发文机关：国家网信办 国家新闻出版署 国家电影局 教育部 工业和信息化部 公安部 文化和旅游部 广电总局发文字号：国信办通字〔2025〕5号来 源：国家网信办网站主题分类：文化、广电、新闻出版\\其他公文种类：成文日期：2025年12月26日标 题：发文机关：国家网信办 国家新闻出版署 国家电影局 教育部 工业和信息化部 公安部 文化和旅游部 广电总局发文字号：国信办通字。","tags":["未成年人","网络信息","身心健康"],"language":"zh"},{"id":"cn-ministry-003","title":"关于印发儿童青少年“五健”促进行动计划（2026—2030年）的通知","issuer":"国家卫生健康委等13部门","doc_no":"","publish_date":"2025-12-30","effective_date":"2025-12-30","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/202512/content_7053270.htm","attachments":[],"summary":"一、总体要求以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届历次全会精神，坚持新时代党的卫生与健康工作方针，落实健康优先发展战略和儿童优先原则，以增进儿童青少年身心健康为目标，坚持预防为主、多病同防共管，推进医校协同、卫体融合、家校共育、社会共治的工作机制更加健全，健康教育和健康促进持续深化，防、筛、诊、治、康一体化服务链条更加完善，儿童青少年健康水平不断提升。","tags":["儿童青少年","心理健康","健康促进"],"language":"zh"},{"id":"cn-ministry-036","title":"关于发布《职业健康监护技术规范》等9项国家职业卫生标准的通告","issuer":"国家卫生健康委","doc_no":"","publish_date":"2025-09-06","effective_date":"2025-09-06","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/202509/content_7039410.htm","attachments":[],"summary":"标 题：发文机关：国家卫生健康委发文字号：国卫通〔2025〕10号来 源：国家卫生健康委网站主题分类：卫生、体育\\卫生公文种类：成文日期：2025年08月20日标 题：发文机关：国家卫生健康委发文字号：国卫通〔2025〕10号来 源：国家卫生健康委网站主题分类：卫生、体育\\卫生公文种类：通告成文日期：2025年08月20日国卫通〔2025〕10号现发布《职业健康监护技术规范》等。","tags":["职业健康","监护规范","心理健康"],"language":"zh"},{"id":"cn-ministry-041","title":"关于印发《健康中国行动—健康环境促进行动实施方案（2025—2030年）》的通知","issuer":"国家疾控局等","doc_no":"","publish_date":"2025-08-05","effective_date":"2025-08-05","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/202508/content_7035320.htm","attachments":[],"summary":"动员群众参与全民健身、体重管理、心理健康等活动，倡导“三减三健”，养成均衡饮食、适度运动、戒烟限酒、规律作息、充足睡眠等健康生活方式，减少电子屏幕依赖。文件围绕健康中国行动、健康环境、健康促进提出具体要求和实施举措，是心理健康相关法律法规与政策体系的重要组成部分。","tags":["健康中国行动","健康环境","健康促进"],"language":"zh"},{"id":"cn-ministry-042","title":"全国爱卫会关于将健康体重管理行动等3个行动纳入健康中国行动的通知","issuer":"全国爱国卫生运动委员会","doc_no":"","publish_date":"2025-04-14","effective_date":"2025-04-14","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/202504/content_7018518.htm","attachments":[],"summary":"标 题：发文机关：全国爱国卫生运动委员会发文字号：全爱卫发〔2025〕2号来 源：国家卫生健康委网站主题分类：卫生、体育\\其他公文种类：成文日期：2025年04月02日标 题：发文机关：全国爱国卫生运动委员会发文字号：全爱卫发〔2025〕2号来 源：国家卫生健康委网站主题分类：卫生、体育\\其他公文种类：通知成文日期：2025年04月02日全爱卫发〔2025〕2号各省、自治区、直。","tags":["健康中国行动","健康体重","健康促进"],"language":"zh"},{"id":"cn-ministry-007","title":"国家卫生健康委等15个部门关于联合印发《应对老年期痴呆国家行动计划（2024—2030年）》的通知","issuer":"国家卫生健康委等15部门","doc_no":"","publish_date":"2025-01-03","effective_date":"2025-01-03","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/202501/content_6996231.htm","attachments":[],"summary":"标 题：发文机关：国家卫生健康委等发文字号：国卫老龄发〔2024〕42号来 源：国家卫生健康委网站主题分类：卫生、体育\\其他公文种类：成文日期：2024年12月31日标 题：发文机关：国家卫生健康委等发文字号：国卫老龄发〔2024〕42号来 源：国家卫生健康委网站主题分类：卫生、体育\\其他公文种类：通知成文日期：2024年12月31日国卫老龄发〔2024〕42号各省、自治区、直。","tags":["老年痴呆","心理健康","行动计划"],"language":"zh"},{"id":"cn-ministry-030","title":"推动新时代新征程12355青少年服务台高质量发展","issuer":"共青团中央、民政部、国家卫生健康委","doc_no":"","publish_date":"2024-06-19","effective_date":"2024-06-19","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gqt.org.cn","source_url":"https://www.gqt.org.cn/xxgk/tngz_gfxwj/gfxwj/202406/t20240619_796325.htm","attachments":[],"summary":"中国共青团网 > 信息公开 > 团内规章和规范性文件 > 规范性文件 > 正文共青团中央 民政部 国家卫生健康委关于推动新时代新征程12355青少年服务台高质量发展的意见中青联发〔2024〕4号服务青少年成长发展是共青团的重要职责，12355青少年服务台是共青团感知青年温度、传递党的温暖的重要载体。","tags":["12355","青少年","心理服务"],"language":"zh"},{"id":"cn-ministry-035","title":"关于进一步推进职业健康保护行动提升劳动者职业健康素养水平的通知","issuer":"国家卫生健康委办公厅等","doc_no":"","publish_date":"2024-01-28","effective_date":"2024-01-28","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/202401/content_6928726.htm","attachments":[],"summary":"聚焦工矿企业或第二、第三产业劳动者集中的社区，结合辖区内常见职业病以及心脑血管、肌肉骨骼、精神心理等方面工作相关疾病特点，通过制作展板、发放手册、播放视频、健康义诊、专家讲座等形式，传播职业病和工作相关疾病防治知识。文件围绕职业健康、劳动者、心理健康提出具体要求和实施举措，是心理健康相关法律法规与政策体系的重要组成部分。","tags":["职业健康","劳动者","心理健康"],"language":"zh"},{"id":"cn-ministry-008","title":"国家卫生健康委办公厅关于开展老年痴呆防治促进行动（2023—2025年）的通知","issuer":"国家卫生健康委办公厅","doc_no":"","publish_date":"2023-06-14","effective_date":"2023-06-14","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/202306/content_6886277.htm","attachments":[],"summary":"在社区健康大讲堂、老年大学等开设老年痴呆防治专题讲座，利用敬老月、老年健康宣传周、世界精神卫生日、世界阿尔茨海默病日等活动和纪念日，举办老年痴呆防治知识宣教活动。文件围绕老年痴呆、防治、老年人心理健康提出具体要求和实施举措，是心理健康相关法律法规与政策体系的重要组成部分。","tags":["老年痴呆","防治","老年人心理健康"],"language":"zh"},{"id":"cn-ministry-032","title":"加强共青团新时代未成年人保护工作","issuer":"共青团中央、全国少工委","doc_no":"","publish_date":"2023-02-09","effective_date":"2023-02-09","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gqt.org.cn","source_url":"https://www.gqt.org.cn/xxgk/tngz_gfxwj/gfxwj/202302/t20230209_790975.htm","attachments":[],"summary":"为深入贯彻习近平总书记关于未成年人保护工作重要指示批示精神，扎实落实《国务院未成年人保护工作领导小组关于加强未成年人保护工作的意见》，就进一步加强共青团新时代未成年人保护工作，提出如下意见。注重道德培育，汲取善用中华传统文化精髓，弘扬红色精神谱系、传扬革命英雄人物事迹，强化社会主义核心价值观教育，发挥榜样示范带动作用，深化劳动实践和志愿服务体验参与，引领未成年人树立正确世界观、人生观、价值观。","tags":["未成年人","心理健康","共青团"],"language":"zh"},{"id":"cn-ministry-026","title":"教育部等十三部门关于健全学校家庭社会协同育人机制的意见","issuer":"教育部等13部门","doc_no":"","publish_date":"2023-01-19","effective_date":"2023-01-19","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2023-01/19/content_5737973.htm","attachments":[],"summary":"为认真贯彻落实党的二十大精神，根据《中华人民共和国家庭教育促进法》《中华人民共和国未成年人保护法》等有关规定，现就健全学校家庭社会协同育人机制提出如下意见。学校要把统筹用好各类社会资源作为强化实践育人的重要途径，积极拓展校外教育空间，着力培养学生社会责任感、创新精神和实践能力。要积极邀请“五老”、劳动模范、道德模范、时代楷模、各类精神文明先进代表、德艺双馨的艺术家等到学校开展宣讲教育活动。","tags":["家校社协同","学生心理健康","育人机制"],"language":"zh"},{"id":"cn-ministry-037","title":"国务院未成年人保护工作领导小组办公室关于开展“情暖新春 共护未来”2023年寒假春节期间困境儿童关爱服务活动的通知","issuer":"国务院未成年人保护工作领导小组办公室","doc_no":"","publish_date":"2023-01-10","effective_date":"2023-01-10","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2023-01/10/content_5736083.htm","attachments":[],"summary":"（四）积极开展心理健康教育指导。组织专业社会组织、社会工作者、志愿者等社会力量，为困境儿童开展爱心陪伴、心理疏导、行为矫治、社会融入和家庭关系调适等关爱服务活动，缓解疫情下儿童产生的心理焦虑，提高儿童的心理健康水平。文件围绕困境儿童、关爱服务、心理健康提出具体要求和实施举措，是心理健康相关法律法规与政策体系的重要组成部分。","tags":["困境儿童","关爱服务","心理健康"],"language":"zh"},{"id":"cn-ministry-031","title":"加强新时代12355青少年服务台建设","issuer":"共青团中央","doc_no":"","publish_date":"2022-10-13","effective_date":"2022-10-13","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gqt.org.cn","source_url":"https://www.gqt.org.cn/xxgk/tngz_gfxwj/gfxwj/202210/t20221013_790065.htm","attachments":[],"summary":"为深入贯彻习近平总书记关于青年工作的重要思想，落实共青团十八大和十八届二中、三中、四中全会精神，提升共青团服务青少年的能力和水平，提出以下意见。围绕“倾听心声、维护权益，专业服务、关爱成长”，落实《中长期青年发展规划（2016—2025年）》工作部署，提升法律、心理核心服务功能，回应青少年亟待解决的成长烦恼和发展难题。","tags":["12355","青少年","权益服务"],"language":"zh"},{"id":"cn-ministry-038","title":"民政部关于开展全国未成年人保护示范创建的通知","issuer":"民政部","doc_no":"","publish_date":"2021-08-19","effective_date":"2021-08-19","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2021-08/19/content_5632252.htm","attachments":[],"summary":"标 题：发文机关：发文字号：民函〔2021〕68号来 源：民政部网站主题分类：民政、扶贫、救灾\\其他公文种类：成文日期：2021年08月18日标 题：发文机关：民政部发文字号：民函〔2021〕68号来 源：民政部网站主题分类：民政、扶贫、救灾\\其他公文种类：通知成文日期：2021年08月18日民函〔2021〕68号各省、自治区、直辖市民政厅（局），计划单列市民政局，新疆生产建设。","tags":["未成年人保护","示范创建","心理健康"],"language":"zh"},{"id":"cn-ministry-005","title":"未成年人学校保护规定","issuer":"教育部","doc_no":"","publish_date":"2021-06-02","effective_date":"2021-06-02","level":"部门规章","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2021-06/02/content_5614946.htm","attachments":[],"summary":"学生之间，在年龄、身体或者人数等方面占优势的一方蓄意或者恶意对另一方实施前款行为，或者以其他方式欺压、侮辱另一方，造成人身伤害、财产损失或者精神损害的，可以认定为构成欺凌。有条件的学校，可以定期组织教职工进行心理健康状况测评，指导、帮助教职工以积极、乐观的心态对待学生。（二）有严重酗酒、滥用精神类药物史的。","tags":["未成年人","学校保护","心理健康"],"language":"zh"},{"id":"cn-ministry-009","title":"教育部办公厅关于进一步加强中小学生睡眠管理工作的通知","issuer":"教育部办公厅","doc_no":"","publish_date":"2021-04-02","effective_date":"2021-04-02","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2021-04/02/content_5597443.htm","attachments":[],"summary":"各地各校要把科学睡眠宣传教育纳入课程教学体系、教师培训内容和家校协同育人机制，通过体育与健康课程、心理健康教育、班团队活动、科普讲座以及家长学校、家长会等多种途径，大力普及科学睡眠知识，广泛宣传充足睡眠对于中小学生健康成长的极端重要性，提高教师思想认识，教育学生养成良好睡眠卫生习惯，引导家长重视做好孩子睡眠管理。","tags":["中小学生","睡眠管理","身心健康"],"language":"zh"},{"id":"cn-ministry-039","title":"关于做好因突发事件影响造成监护缺失未成年人救助保护工作的意见","issuer":"民政部等","doc_no":"","publish_date":"2021-01-26","effective_date":"2021-01-26","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2021-01/26/content_5582579.htm","attachments":[],"summary":"为贯彻落实习近平总书记重要指示精神和《民法典》、《未成年人保护法》有关规定，切实做好因突发事件影响造成监护缺失未成年人（以下简称监护缺失未成年人）的救助保护工作，提出如下意见：一、明确工作对象1.本意见所指突发事件是指突然发生，造成或者可能造成严重社会危害，需要采取应急处置措施予以应对的自然灾害、事故灾难、公共卫生事件和社会安全事件。","tags":["未成年人","救助保护","心理健康"],"language":"zh"},{"id":"cn-ministry-040","title":"关于进一步加强涉未成年人网课平台规范管理的通知","issuer":"中央网信办、教育部","doc_no":"","publish_date":"2020-12-04","effective_date":"2020-12-04","level":"部门规范性文件","region":"中国·国家","category":"ministry","source_site":"www.gov.cn","source_url":"https://www.gov.cn/zhengce/zhengceku/2020-12/04/content_5566923.htm","attachments":[],"summary":"标 题：发文机关：网信办 教育部发文字号：来 源：网信办网站主题分类：科技、教育\\教育公文种类：成文日期：2020年11月27日标 题：发文机关：网信办 教育部发文字号：来 源：网信办网站主题分类：科技、教育\\教育公文种类：通知成文日期：2020年11月27日各省、自治区、直辖市网信办、教育厅（教委），新疆生产建设兵团网信办、教育局：为切实保障优质线上教育资源供给，推动涉未成年。","tags":["未成年人","网课平台","身心健康"],"language":"zh"},{"id":"cn-local-028","title":"山西省关于印发健全社会心理服务体系和危机干预机制实施方案的通知","issuer":"山西省卫生健康委等","doc_no":"","publish_date":"2026-04-10","effective_date":"2026-04-10","level":"地方规范性文件","region":"中国·山西","category":"local","source_site":"wjw.shanxi.gov.cn","source_url":"http://wjw.shanxi.gov.cn/tzgg/sjzcwj/202604/t20260410_10101113.shtml","attachments":[],"summary":"国卫医政发〔2026〕8号各省、自治区、直辖市及新疆生产建设兵团有关部门：为深入贯彻落实党的二十届三中、四中全会精神，健全社会心理服务体系和危机干预机制，我们制定了《健全社会心理服务体系和危机干预机制实施方案》，现予印发，请认真组织实施。到2030年，覆盖全人群、全生命周期的社会心理服务体系和危机干预机制基本健全。","tags":["社会心理服务","危机干预","山西"],"language":"zh"},{"id":"cn-local-014","title":"苏州市中小学生心理健康促进条例","issuer":"苏州市人民代表大会常务委员会","doc_no":"","publish_date":"2026-01-29","effective_date":"2026-05-01","level":"地方性法规","region":"中国·江苏","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff8081819c46fdc3019c9418fd1b3853","attachments":[],"summary":"第一条 为了促进中小学生心理健康，增进家庭幸福与社会和谐，培养德智体美劳全面发展的社会主义建设者和接班人，根据有关法律、法规，结合本市实际，制定本条例。第二条 本市行政区域内中小学生心理健康促进工作以及相关活动，适用本条例。第三条 学生心理健康促进工作以及相关活动坚持以人为本、健康第一、系统推进、科学规范的原则，遵循学生成长规律，尊重学生人格尊严，保护学生隐私权和个人信息，促进学生全面发展。","tags":["精神卫生","心理健康","江苏"],"language":"zh"},{"id":"cn-local-011","title":"宁夏回族自治区精神卫生条例","issuer":"宁夏回族自治区人大常务委员会","doc_no":"","publish_date":"2025-07-31","effective_date":"2025-09-01","level":"地方性法规","region":"中国·宁夏","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff80818198a7ecd40198f3a6fe540f3a","attachments":[],"summary":"第一条 为了发展精神卫生事业，规范精神卫生服务，增进公民心理健康，维护精神障碍患者的合法权益，促进社会和谐稳定，根据《中华人民共和国精神卫生法》等法律、行政法规，结合自治区实际，制定本条例。第二条 在自治区行政区域内开展维护和增进公民心理健康、预防和治疗精神障碍、促进精神障碍患者康复的活动，适用本条例。","tags":["精神卫生","心理健康","宁夏"],"language":"zh"},{"id":"cn-local-038","title":"青海省“儿科和精神卫生服务年”行动实施方案（2025—2027年）","issuer":"青海省卫生健康委、省疾控局","doc_no":"","publish_date":"2025-07-07","effective_date":"2025-07-07","level":"地方规范性文件","region":"中国·青海","category":"local","source_site":"wsjkw.qinghai.gov.cn","source_url":"https://wsjkw.qinghai.gov.cn/zwgk/jgzn/nsjg/yzygj/gzdt_6103/202507/t20250707_306578.html","attachments":[],"summary":"青海省卫生健康委      青海省疾病预防控制局2025年6月18日“儿科和精神卫生服务年”行动实施方案（2025—2027年）根据国家卫生健康委等4部门《关于开展“儿科和精神卫生服务年”行动（2025—2027年）的通知》（国卫医政函〔2025〕93号）要求，为进一步做好儿科和精神卫生服务相关工作，切实提高群众看病就医获得感，结合我省实际，制定本方案。","tags":["精神卫生","服务年","青海"],"language":"zh"},{"id":"cn-local-033","title":"江西省儿童青少年心理健康促进行动方案（2025—2027年）","issuer":"江西省人民政府办公厅","doc_no":"","publish_date":"2025-07-01","effective_date":"2025-07-01","level":"地方规范性文件","region":"中国·江西","category":"local","source_site":"www.jiangxi.gov.cn","source_url":"http://www.jiangxi.gov.cn/jxsrmzf/zcwj103/m/content/content_1940341505439506432.html","attachments":[],"summary":"2025年7月1日（此件主动公开）江西省儿童青少年心理健康促进行动方案（2025-2027年）儿童青少年健康成长关系到千家万户的幸福，关乎国家发展和民族未来。全省儿童青少年心理健康体系建设目标二、构建共建共治共享的心理健康工作体系（三）构建精神卫生服务网络。推动二级及以上精神专科医院心理门诊设置全覆盖。","tags":["儿童青少年","心理健康","江西"],"language":"zh"},{"id":"cn-local-012","title":"湖南省促进学生心理健康条例","issuer":"湖南省人民代表大会常务委员会","doc_no":"","publish_date":"2025-05-29","effective_date":"2025-07-01","level":"地方性法规","region":"中国·湖南","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff808181971b897301976232010f0610","attachments":[],"summary":"第一条 为了促进学生心理健康，培养德智体美劳全面发展的社会主义建设者和接班人，根据有关法律、行政法规，结合本省实际，制定本条例。第二条 促进学生心理健康应当全面贯彻党的教育方针，坚持教育必须为社会主义现代化建设服务、为人民服务，必须与生产劳动和社会实践相结合，遵循全面发展、以人为本、健康第一、提升能力、系统治理的原则。","tags":["精神卫生","心理健康","湖南"],"language":"zh"},{"id":"cn-local-019","title":"无锡市精神卫生条例","issuer":"无锡市人民代表大会常务委员会","doc_no":"","publish_date":"2025-01-26","effective_date":"2025-03-01","level":"地方性法规","region":"中国·江苏","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff808181927f127601954124aafd6596","attachments":[],"summary":"第一条 为了发展精神卫生事业，规范精神卫生服务，促进全民心理健康，保障精神障碍患者的合法权益，根据《中华人民共和国精神卫生法》、《江苏省精神卫生条例》等法律、法规，结合本市实际，制定本条例。第二条 本市行政区域内心理健康促进与精神障碍的预防、诊治、康复，严重精神障碍患者的服务与管理等相关活动，适用本条例。","tags":["精神卫生","心理健康","江苏"],"language":"zh"},{"id":"cn-local-006","title":"重庆市精神卫生条例","issuer":"重庆市人民代表大会常务委员会","doc_no":"","publish_date":"2024-11-28","effective_date":"2025-03-01","level":"地方性法规","region":"中国·重庆","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff808181927f09310193ce6725550a38","attachments":[],"summary":"第一条 为了发展精神卫生事业，规范精神卫生服务，维护精神障碍患者的合法权益，促进公民心理健康，根据《中华人民共和国精神卫生法》等法律、行政法规，结合本市实际，制定本条例。第二条 本市行政区域内公民心理健康维护与增进、精神障碍预防与诊断治疗、精神障碍患者康复与看护、严重精神障碍患者服务与管理等活动，适用本条例。","tags":["精神卫生","心理健康","重庆"],"language":"zh"},{"id":"cn-local-013","title":"广州市中小学生心理健康促进条例","issuer":"广州市人民代表大会常务委员会","doc_no":"","publish_date":"2024-10-11","effective_date":"2024-11-01","level":"地方性法规","region":"中国·广东","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff808181927f0931019304559eba6f6f","attachments":[],"summary":"第一条 为了培育中小学生阳光乐观、意志坚强、积极进取的心理品质，预防中小学生的心理行为问题，培养德智体美劳全面发展的社会主义建设者和接班人，根据有关法律法规，结合本市实际制定本条例。第二条 本条例适用于本市行政区域内中小学生心理健康促进工作。第三条 市、区人民政府应当建立中小学生心理健康促进工作联席会议制度，加强中小学生心理健康服务体系建设，保障中小学生心理健康工作经费。","tags":["精神卫生","心理健康","广东"],"language":"zh"},{"id":"cn-local-008","title":"贵州省精神卫生条例","issuer":"贵州省人民代表大会常务委员会","doc_no":"","publish_date":"2024-07-31","effective_date":"2024-10-10","level":"地方性法规","region":"中国·贵州","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff8081819150444501915a1586151307","attachments":[],"summary":"第一条 为了发展精神卫生事业，规范精神卫生服务，促进公民心理健康，维护精神障碍患者的合法权益，根据《中华人民共和国精神卫生法》和有关法律、行政法规的规定，结合本省实际，制定本条例。第二条 本省行政区域内的精神卫生工作适用本条例。本条例所称精神卫生工作，是指心理健康促进和精神障碍的预防、诊断、治疗、康复以及相关的服务管理与保障活动。","tags":["精神卫生","心理健康","贵州"],"language":"zh"},{"id":"cn-local-007","title":"四川省精神卫生条例","issuer":"四川省人民代表大会常务委员会","doc_no":"","publish_date":"2024-05-29","effective_date":"2024-07-01","level":"地方性法规","region":"中国·四川","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff8081819014e99a019039837eba4f9d","attachments":[],"summary":"第一条 为了推进健康四川建设，规范精神卫生服务，促进公民心理健康，维护精神障碍患者的合法权益，根据《中华人民共和国精神卫生法》等法律、行政法规，结合四川省实际，制定本条例。第二条 在四川省行政区域内开展公民心理健康促进和精神障碍预防、诊断、治疗、康复等活动，适用本条例。第三条 全社会应当尊重、理解、关爱精神障碍患者。","tags":["精神卫生","心理健康","四川"],"language":"zh"},{"id":"cn-local-010","title":"广西壮族自治区精神卫生条例","issuer":"广西壮族自治区人大常务委员会","doc_no":"","publish_date":"2024-03-28","effective_date":"2024-07-01","level":"地方性法规","region":"中国·广西","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff808181927f09310192d5e02eca2bf7","attachments":[],"summary":"第一条 为了发展精神卫生事业，规范和完善精神卫生服务，促进公民心理健康，维护精神障碍患者的合法权益，根据《中华人民共和国精神卫生法》等有关法律、行政法规，结合本自治区实际，制定本条例。第二条 本自治区行政区域内开展维护和增进公民心理健康，预防、诊断、治疗精神障碍，促进精神障碍患者康复等活动，适用本条例。","tags":["精神卫生","心理健康","广西"],"language":"zh"},{"id":"cn-local-023","title":"天津市全面加强和改进新时代学生心理健康工作行动方案","issuer":"天津市教委等16部门","doc_no":"","publish_date":"2024-02-23","effective_date":"2024-02-23","level":"地方规范性文件","region":"中国·天津","category":"local","source_site":"jy.tj.gov.cn","source_url":"https://jy.tj.gov.cn/ZWGK_52172/zcwj/sjwwj/202402/t20240223_6543177.html","attachments":[],"summary":"天津市卫生健康委员会;二、主要任务（一）实施五育融合联动计划1.坚持把心理健康教育贯穿德育始终。将心理健康教育作为“三全育人”重要内容，积极构建“大思政”格局，引导学生扣好人生第一粒扣子，在实施德育中促进学生心理素质提高。2.坚持把心理健康教育贯穿智育始终。建立教师包联学生心理健康工作制度，实现覆盖全体学生。","tags":["学生心理健康","行动方案","天津"],"language":"zh"},{"id":"cn-local-027","title":"关于贯彻落实《全面加强和改进新时代学生心理健康工作专项行动计划（2023—2025年）》的通知","issuer":"山西省教育厅","doc_no":"","publish_date":"2023-10-09","effective_date":"2023-10-09","level":"地方规范性文件","region":"中国·山西","category":"local","source_site":"jyt.shanxi.gov.cn","source_url":"https://jyt.shanxi.gov.cn/xwzx/ggtz/202310/t20231009_9382717.html","attachments":[],"summary":"晋教政〔2023〕6号各市教育局、市检察院、市委宣传部、市委网信办、市科技局、市公安局、市民政局、市财政局、市卫生健康委、市文化和旅游局、市体育局、市妇儿工委办公室、团市委、市妇联、市关工委、市科协，各高等学校、省属中职学校：现就贯彻落实教育部等十七部门《全面加强和改进新时代学生心理健康工作专项行动计划（2023—2025年）》通知如下。","tags":["学生心理健康","贯彻落实","山西"],"language":"zh"},{"id":"cn-local-017","title":"滨州市社会心理服务条例","issuer":"滨州市人民代表大会常务委员会","doc_no":"","publish_date":"2023-10-07","effective_date":"2024-01-01","level":"地方性法规","region":"中国·山东","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff8081818b6b8423018b6f366c250c9b","attachments":[],"summary":"第一条 为了规范社会心理服务工作，提升公众心理健康水平，培育自尊自信、理性平和、积极向上的社会心态，有效化解社会矛盾，推进社会治理现代化，实现社会安定和谐进步，根据有关法律法规，结合本市实际，制定本条例。第二条 本市行政区域内社会心理服务工作及其相关活动适用本条例。本条例所称社会心理服务机构，是指精神卫生医疗机构、心理咨询室、社会工作室以及各类社会心理服务场所等提供心理健康服务的机构或者组织。","tags":["精神卫生","心理健康","山东"],"language":"zh"},{"id":"cn-local-016","title":"曲靖市严重精神障碍患者救助保障条例","issuer":"曲靖市人民代表大会常务委员会","doc_no":"","publish_date":"2023-09-27","effective_date":"2023-11-01","level":"地方性法规","region":"中国·云南","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff8081818b287dfc018b458fd2e004c2","attachments":[],"summary":"第一条 为了加强严重精神障碍患者救助保障工作，维护严重精神障碍患者的合法权益，促进社会和谐稳定，根据《中华人民共和国精神卫生法》等法律、法规，结合本市实际，制定本条例。第二条 本市行政区域内的严重精神障碍患者救助保障及相关工作适用本条例。第四条 市、县（市、区）人民政府组织领导本行政区域内的严重精神障碍患者救助保障工作，应当将严重精神障碍患者救助保障工作经费纳入预算，及时足额拨付专项资金。","tags":["精神卫生","心理健康","云南"],"language":"zh"},{"id":"cn-local-025","title":"全面加强和改进新时代学生心理健康工作专项行动计划（2023—2025年）实施方案","issuer":"河北省教育厅等17部门","doc_no":"","publish_date":"2023-08-04","effective_date":"2023-08-04","level":"地方规范性文件","region":"中国·河北","category":"local","source_site":"jyt.hebei.gov.cn","source_url":"http://jyt.hebei.gov.cn/col/1410097726928/2023/08/04/1691130667367.html","attachments":[],"summary":"一、总体要求以习近平新时代中国特色社会主义思想为指导，全面贯彻党的教育方针，落实立德树人根本任务，坚持健康第一的教育理念，切实把心理健康工作摆在更加突出位置，促进学生思想道德素质、科学文化素质和身心健康素质协调发展，培养担当民族复兴大任的时代新人。配备专（兼）职心理健康教育教师的学校比例达到95%。","tags":["学生心理健康","专项行动","河北"],"language":"zh"},{"id":"cn-local-031","title":"关于转发《全面加强和改进新时代学生心理健康工作专项行动计划（2023—2025年）》的通知","issuer":"中共福建省委教育工委等16部门","doc_no":"","publish_date":"2023-07-17","effective_date":"2023-07-17","level":"地方规范性文件","region":"中国·福建","category":"local","source_site":"jyt.fj.gov.cn","source_url":"https://jyt.fj.gov.cn/xxgk/zywj/202307/t20230717_6208558.htm","attachments":[],"summary":"各地各校要提升政治站位，加强对学生心理健康教育工作的统筹规划，将学生心理健康工作纳入对市级人民政府履行教育职责的评价，将心理健康教育工作列入年度工作计划，作为学校办学质量评估标准体系、文明校园创建以及学校领导班子和领导干部年度考核评价的重要依据。各校要将心理健康教育纳入学校改革发展整体规划，纳入人才培养体系、思想政治工作体系，构建校内各部门统筹协调机制，研究制定心理健康教育工作规划和相关制度。","tags":["学生心理健康","专项行动","福建"],"language":"zh"},{"id":"cn-local-030","title":"安徽省教育厅关于全面加强和改进新时代中小学心理健康教育工作的意见","issuer":"安徽省教育厅","doc_no":"","publish_date":"2023-01-01","effective_date":"2023-01-01","level":"地方规范性文件","region":"中国·安徽","category":"local","source_site":"jyt.ah.gov.cn","source_url":"https://jyt.ah.gov.cn/group3/M00/10/FA/wKg86mcHNXSAabtDAASAgRBDh3c575.pdf","attachments":[],"summary":"一、总体要求以习近平新时代中国特色社会主义思想为指导，全面贯彻党的教育方针，把心理健康教育作为落实立德树人根本任务的重要内容，坚持全面发展，坚持健康第一，坚持提升能力，坚持系统治理，构建形成高质量的中小学心理健康教育工作体系。二、主要任务1.开齐开好心理健康教育课程。发挥课堂教学主渠道作用，帮助学生掌握心理健康知识和技能，树立自助互助求助意识，学会理性面对挫折和困难。","tags":["中小学","心理健康教育","安徽"],"language":"zh"},{"id":"cn-local-002","title":"辽宁省精神卫生条例","issuer":"辽宁省人民代表大会常务委员会","doc_no":"","publish_date":"2022-05-31","effective_date":"2022-10-01","level":"地方性法规","region":"中国·辽宁","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=ff80818181951e170181a45217cb406d","attachments":[],"summary":"第一条 为了实施《中华人民共和国精神卫生法》，加强精神卫生服务能力建设和提高精神障碍患者医疗保障水平，维护精神障碍患者的合法权益，促进社会和谐稳定，制定本条例。第二条 全社会应当尊重、理解、关爱精神障碍患者，依法保护精神障碍患者的人格尊严、人身和财产安全。除依法履行职责需要外，有关单位和个人应当对精神障碍患者的姓名、肖像、住址、工作单位、病历资料以及其他可能推断出其身份的信息予以保密。","tags":["精神卫生","心理健康","辽宁"],"language":"zh"},{"id":"cn-local-032","title":"江西省人民政府办公厅印发关于加强和改进新时代学生心理健康教育工作实施方案的通知","issuer":"江西省人民政府办公厅","doc_no":"","publish_date":"2022-03-19","effective_date":"2022-03-19","level":"地方规范性文件","region":"中国·江西","category":"local","source_site":"www.jiangxi.gov.cn","source_url":"https://www.jiangxi.gov.cn/jxsrmzf/ndqzd135/pc/content/content_1818669210658615296.html","attachments":[],"summary":"2022年3月18日（此件主动公开）关于加强和改进新时代学生心理健康教育工作实施方案为深入贯彻落实习近平总书记关于学生心理健康工作的重要指示批示和全国教育大会精神，进一步加强和改进新时代我省学生心理健康教育，不断增强学生心理健康教育工作的针对性和实效性，着力提升学生心理健康素养，现结合我省学生心理健康教育工作实际，制定如下实施方案。","tags":["学生心理健康","实施方案","江西"],"language":"zh"},{"id":"cn-local-022","title":"天津市加强精神卫生综合管理工作实施方案","issuer":"天津市人民政府办公厅","doc_no":"","publish_date":"2020-05-19","effective_date":"2020-05-19","level":"地方规范性文件","region":"中国·天津","category":"local","source_site":"www.tj.gov.cn","source_url":"https://www.tj.gov.cn/zwgk/szfwj/tjsrmzfbgt/202005/t20200519_2370667.html","attachments":[],"summary":"天津市人民政府办公厅2020年3月24日为进一步完善本市精神障碍预防、治疗、康复和心理健康促进工作模式，推进健康天津、平安天津建设，维护社会和谐稳定，特制定本方案。二、工作目标（一）精神卫生服务体系进一步完善。到2020年，研究推进天津市安定医院心理健康中心、天津市安定医院分院等建设项目立项。","tags":["精神卫生","社会心理服务","天津"],"language":"zh"},{"id":"cn-local-004","title":"浙江省精神卫生条例","issuer":"浙江省人民代表大会常务委员会","doc_no":"","publish_date":"2019-09-27","effective_date":"2019-12-01","level":"地方性法规","region":"中国·浙江","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=2c90e5ba6a291d8f016e01fd8a530724","attachments":[],"summary":"（2019年9月27日浙江省第十三届人民代表大会常务委员会第十四次会议通过）第一条  为了发展精神卫生事业，规范精神卫生服务，促进公民心理健康，维护精神障碍患者的合法权益，根据《中华人民共和国精神卫生法》和有关法律、行政法规，结合本省实际，制定本条例。第二条  本省行政区域内开展公民心理健康促进和精神障碍预防、诊断、治疗、康复等活动，适用本条例。","tags":["精神卫生","心理健康","浙江"],"language":"zh"},{"id":"cn-local-005","title":"山东省精神卫生条例","issuer":"山东省人民代表大会常务委员会","doc_no":"","publish_date":"2019-03-29","effective_date":"2019-06-01","level":"地方性法规","region":"中国·山东","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=2c90e5ba6a291d8f016a2a10b7f0009b","attachments":[],"summary":"（2019年3月29日山东省第十三届人民代表大会常务委员会第十一次会议通过）目  录第一条  为了发展精神卫生事业，规范精神卫生服务，促进公民心理健康，维护精神障碍患者的合法权益，根据《中华人民共和国精神卫生法》等法律、行政法规，结合本省实际，制定本条例。第二条  本省行政区域内公民心理健康维护和增进、精神障碍预防和治疗、精神障碍患者康复、严重精神障碍服务管理等活动，适用本条例。","tags":["精神卫生","心理健康","山东"],"language":"zh"},{"id":"cn-local-024","title":"关于加强心理健康服务的实施意见","issuer":"河北省卫生健康委等","doc_no":"","publish_date":"2018-07-01","effective_date":"2018-07-01","level":"地方规范性文件","region":"中国·河北","category":"local","source_site":"wsjkw.hebei.gov.cn","source_url":"http://wsjkw.hebei.gov.cn/tzgg/343509.jhtml","attachments":[],"summary":"《关于加强心理健康服务的实施意见》由河北省卫生健康委等于2018年发布，属于地方规范性文件，主要涉及心理健康服务、实施意见、河北等内容。该文件为心理健康相关工作的政策依据之一，可用于了解相应层级在精神卫生服务、心理服务体系建设或重点人群心理健康促进方面的制度安排。","tags":["心理健康服务","实施意见","河北"],"language":"zh"},{"id":"cn-local-020","title":"杭州市精神卫生条例","issuer":"杭州市人民代表大会常务委员会","doc_no":"","publish_date":"2016-10-20","effective_date":"","level":"地方性法规","region":"中国·浙江","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=4028abcc61277793016127fd5ce63e61","attachments":[],"summary":"第一条 为了发展精神卫生事业，规范精神卫生服务，维护精神障碍患者的合法权益，根据《中华人民共和国精神卫生法》等法律、法规，结合本市实际，制定本条例。第二条 本市行政区域内的精神卫生工作适用本条例。本条例所称精神卫生工作，是指心理健康促进和精神障碍的预防、治疗、康复等精神卫生服务以及相关的管理活动。","tags":["精神卫生","心理健康","浙江"],"language":"zh"},{"id":"cn-local-009","title":"甘肃省精神卫生条例","issuer":"甘肃省人民代表大会常务委员会","doc_no":"","publish_date":"2016-09-29","effective_date":"","level":"地方性法规","region":"中国·甘肃","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=4028abcc61277793016127ecf4642cac","attachments":[],"summary":"第一条  根据《中华人民共和国精神卫生法》和有关法律法规，结合本省实际，制定本条例。第二条  在本省行政区域内开展维护和增进公民心理健康、预防和治疗精神障碍、促进精神障碍患者康复的活动，适用本条例。乡镇人民政府和街道办事处根据辖区的实际情况，组织开展心理健康活动，预防精神障碍发生，促进精神障碍患者康复等工作。","tags":["精神卫生","心理健康","甘肃"],"language":"zh"},{"id":"cn-local-021","title":"武汉市精神卫生条例","issuer":"武汉市人民代表大会常务委员会","doc_no":"","publish_date":"2015-08-17","effective_date":"","level":"地方性法规","region":"中国·湖北","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=4028abcc612777930161286fed922e0c","attachments":[],"summary":"第一条 为了加强精神卫生工作，提高公民心理健康水平，保障精神障碍者合法权益，促进社会和谐稳定，根据有关法律、法规，结合本市实际，制定本条例。第二条 本市行政区域内的精神卫生事业促进和精神障碍的预防控制、诊断治疗、康复服务以及相关行政管理活动适用本条例。第三条 精神卫生工作坚持预防为主、防治结合、重点干预、广泛覆盖、依法管理的原则。","tags":["精神卫生","心理健康","湖北"],"language":"zh"},{"id":"cn-local-018","title":"长春市精神卫生条例","issuer":"长春市人民代表大会常务委员会","doc_no":"","publish_date":"2015-04-21","effective_date":"","level":"地方性法规","region":"中国·吉林","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=4028abcc61277793016127ec75392c30","attachments":[],"summary":"第一条 为了进一步促进精神卫生事业发展，提高公民心理健康水平，规范精神卫生服务，维护精神障碍患者的合法权益，根据有关法律、法规，结合本市实际，制定本条例。第二条 本市行政区域内开展维护和增进公民心理健康、预防和治疗精神障碍、促进精神障碍患者康复的活动，适用本条例。第三条 精神卫生工作贯彻预防为主的方针。","tags":["精神卫生","心理健康","吉林"],"language":"zh"},{"id":"cn-local-003","title":"上海市精神卫生条例","issuer":"上海市人民代表大会常务委员会","doc_no":"","publish_date":"2014-11-20","effective_date":"2015-03-01","level":"地方性法规","region":"中国·上海","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=4028abcc612777930161285355ba12f4","attachments":[],"summary":"目    录第一条  为了发展精神卫生事业，规范和完善精神卫生服务，维护精神障碍患者的合法权益，根据《中华人民共和国精神卫生法》，结合本市实际，制定本条例。第二条  本市行政区域内开展维护和增进市民心理健康、预防和治疗精神障碍、促进精神障碍患者康复等活动，推进精神卫生服务体系建设，适用本条例。","tags":["精神卫生","心理健康","上海"],"language":"zh"},{"id":"cn-local-015","title":"深圳经济特区心理卫生条例","issuer":"深圳市人民代表大会常务委员会","doc_no":"","publish_date":"2011-09-29","effective_date":"","level":"地方性法规","region":"中国·广东","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=4028abcc612777930161281ae0f15bef","attachments":[],"summary":"（2011年8月30日深圳市第五届人民代表大会常务委员会第十次会议通过）目    录第一条  为了提高市民的心理健康水平，保障心理咨询来访者、精神障碍患者的合法权益，规范心理咨询和医疗服务，有效预防和治疗精神障碍，促进心理卫生事业发展，建设和谐社会，根据有关法律、法规的基本原则，结合深圳经济特区（以下简称特区）实际，制定本条例。","tags":["精神卫生","心理健康","广东"],"language":"zh"},{"id":"cn-local-001","title":"北京市精神卫生条例","issuer":"北京市人民代表大会常务委员会","doc_no":"","publish_date":"2006-12-08","effective_date":"2007-03-01","level":"地方性法规","region":"中国·北京","category":"local","source_site":"国家法律法规数据库（flk.npc.gov.cn）","source_url":"https://flk.npc.gov.cn/detail?bbbs=4028abcc612777930161280f523b4fb8","attachments":[],"summary":"（2006年12月8日北京市第十二届人民代表大会常务委员会第三十三次会议通过）目    录第一条  为了加强精神卫生工作，提高公民的精神健康水平，保障精神疾病患者的合法权益，促进社会的和谐稳定，根据有关法律、法规，结合本市实际情况，制定本条例。第二条  本条例适用于本市行政区域内的精神健康促进和精神疾病的预防、诊断、治疗、康复等精神卫生服务以及相关的行政管理活动。","tags":["精神卫生","心理健康","北京"],"language":"zh"},{"id":"cn-local-039","title":"青海省国民健康“十五五”规划","issuer":"青海省人民政府","doc_no":"","publish_date":"2026-08-03","effective_date":"2026-08-03","level":"地方规范性文件","region":"中国·青海","category":"local","source_site":"wsjkw.qinghai.gov.cn","source_url":"https://wsjkw.qinghai.gov.cn/zwxx/ttxx/202608/t20260803_418546.html","attachments":[],"summary":"“十五五”时期是基本实现社会主义现代化的关键时期，为明确未来五年青海省国民健康发展目标任务和重点措施，加快建设健康青海，根据《青海省国民经济和社会发展第十五个五年规划纲要》，编制本规划。健全心理健康和精神卫生服务体系及危机干预机制，推动二级以上综合医院普遍开设精神科，拓宽心理援助热线服务覆盖面。","tags":["国民健康规划","心理健康","青海"],"language":"zh"},{"id":"cn-local-035","title":"河南省公共卫生体系建设三年行动计划（2023—2025年）","issuer":"河南省人民政府办公厅","doc_no":"","publish_date":"2023-07-20","effective_date":"2023-07-20","level":"地方规范性文件","region":"中国·河南","category":"local","source_site":"www.henan.gov.cn","source_url":"https://www.henan.gov.cn/2023/07-20/2781542.html","attachments":[],"summary":"以习近平新时代中国特色社会主义思想为指导，全面贯彻党的二十大精神和习近平总书记关于卫生健康工作的重要论述，坚持以人民健康为中心，聚焦补短板、堵漏洞、强弱项、扬优势，统筹力量加强公共卫生体系建设，提升公共卫生服务能力，全面维护人民群众生命安全和身体健康，为健康河南建设奠定坚实基础。","tags":["公共卫生","心理健康服务","河南"],"language":"zh"},{"id":"cn-local-029","title":"黑龙江省全面加强和改进新时代学校卫生与健康教育工作实施方案","issuer":"黑龙江省教育厅等5部门","doc_no":"","publish_date":"2022-12-01","effective_date":"2022-12-01","level":"地方规范性文件","region":"中国·黑龙江","category":"local","source_site":"www.hlj.gov.cn","source_url":"https://www.hlj.gov.cn/hlj/c108427/202212/c00_31506169.shtml","attachments":[],"summary":"一、指导思想以习近平新时代中国特色社会主义思想为指导，深入学习贯彻党的二十大精神，全面贯彻党的教育方针，落实立德树人根本任务，坚持健康第一教育理念，把全面提升学生健康素养纳入高质量教育体系，作为学校教育重要目标和评价标准，深化学校健康教育改革，夯实学校卫生条件保障，构建高质量学校卫生与健康教育体系，促进学生身心健康、养成健康生活方式，培养德智体美劳全面发展的社会主义建设者和接班人。","tags":["学校卫生","心理健康教育","黑龙江"],"language":"zh"},{"id":"cn-local-034","title":"健康中原行动（2020—2030年）","issuer":"健康中原行动推进委员会","doc_no":"","publish_date":"2020-10-14","effective_date":"2020-10-14","level":"地方规范性文件","region":"中国·河南","category":"local","source_site":"wsjkw.henan.gov.cn","source_url":"https://wsjkw.henan.gov.cn/2020/10-14/1821346.html","attachments":[],"summary":"到2022年，促进全民健康的政策体系基本建立，全民健康素养水平稳步提高，健康生活方式加快推广，重大慢性病发病率上升趋势得到遏制，重点传染病、严重精神障碍、地方病、职业病得到有效防控，致残和死亡风险逐步降低，重点人群健康状况显著改善，人均预期寿命达到全国平均水平。（省卫生健康委负责）12.大力开展精神文明创建。","tags":["健康中原","心理健康促进行动","河南"],"language":"zh"},{"id":"cn-local-037","title":"陕西省人民政府关于推进健康陕西行动的实施意见","issuer":"陕西省人民政府","doc_no":"","publish_date":"2020-06-18","effective_date":"2020-06-18","level":"地方规范性文件","region":"中国·陕西","category":"local","source_site":"www.shaanxi.gov.cn","source_url":"http://www.shaanxi.gov.cn/zfxxgk/zfgb/2020/d11q/202006/t20200618_1728514.html","attachments":[],"summary":"政府公报公报详情陕政发〔2020〕7号2020-06-18 01:23各设区市人民政府，省人民政府各工作部门、各直属机构：为深入实施健康中国战略，推进健康陕西行动，根据《国务院关于实施健康中国行动的意见》(国发〔2019〕13号)和《中共陕西省委陕西省人民政府关于印发〈“健康陕西2030”规划纲要〉的通知》（陕发〔2017〕16号）精神，现提出以下实施意见。","tags":["健康陕西","心理健康促进行动","陕西"],"language":"zh"},{"id":"cn-local-036","title":"健康海南行动实施方案","issuer":"海南省人民政府","doc_no":"","publish_date":"2020-03-01","effective_date":"2020-03-01","level":"地方规范性文件","region":"中国·海南","category":"local","source_site":"www.hainan.gov.cn","source_url":"https://www.hainan.gov.cn/hainan/flfgxzgfxwj/202003/14b6d2ad20244f46ab323c9cc45934b4.shtml","attachments":[],"summary":"一、指导思想以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中、四中全会及省第七次党代会精神，坚持以人民为中心的发展思想，贯彻新时代卫生与健康工作方针，加快推动卫生健康理念和服务方式从以治病为中心向以人民健康为中心转变。开展老年心理健康与精神关怀服务，推动安宁疗护服务。","tags":["健康海南","心理健康促进行动","海南"],"language":"zh"},{"id":"cn-local-026","title":"山西省人民政府关于推进健康中国·山西行动的实施意见","issuer":"山西省人民政府","doc_no":"","publish_date":"2020-01-01","effective_date":"2020-01-01","level":"地方规范性文件","region":"中国·山西","category":"local","source_site":"www.shanxi.gov.cn","source_url":"https://www.shanxi.gov.cn/zfxxgk/zfcbw/zfgb2/2020nzfgb_76619/d1q_76620/szfwj_77947/202205/P020220513488408540870.pdf","attachments":[],"summary":"山西省人民政府文件晋政发〔2019〕27号山西省人民政府关于推进健康中国·山西行动的实施意见各市、县人民政府,省人民政府各委、办、厅、局:为贯彻落实健康中国战略,推进健康中国·山西行动,根据《“健康中国2030”规划纲要》、《国务院关于实施健康中国行动的意见》(国发〔2019〕13号)及《“健康山西2030”规划纲要》,提出以下实施意见。","tags":["健康中国行动","心理健康促进行动","山西"],"language":"zh"},{"id":"intl-012","title":"Suicide","issuer":"World Health Organization","doc_no":"","publish_date":"2026-11-03","effective_date":"2026-11-03","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/news-room/fact-sheets/detail/suicide","attachments":[],"summary":"世界卫生组织自杀实况报道，提供全球自杀死亡人数、年龄分布与地区差异等关键数据，指出自杀是可预防的公共卫生问题。报道梳理自杀的危险因素与保护因素，介绍限制手段可及性、媒体负责任报道、青少年生活技能培养、随访与危机干预等有效策略，并说明世卫组织LIVE LIFE倡议与国家自杀预防战略的最新要求。","tags":["自杀","预防","全球负担"],"language":"en"},{"id":"intl-016","title":"Dementia","issuer":"World Health Organization","doc_no":"","publish_date":"2026-10-26","effective_date":"2026-10-26","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/news-room/fact-sheets/detail/dementia","attachments":[],"summary":"世界卫生组织痴呆实况报道，指出全球痴呆患者数量持续增长，阿尔茨海默病是最常见类型，介绍其认知功能减退、行为心理症状与照护负担。报道强调目前尚无治愈手段，但可通过危险因素干预、早期诊断、认知促进与照护者支持改善生活质量，并介绍世卫组织全球痴呆行动计划及《应对老年期痴呆全球行动计划》的相关要求。","tags":["痴呆","老年心理健康","照护"],"language":"en"},{"id":"intl-018","title":"Anxiety disorders","issuer":"World Health Organization","doc_no":"","publish_date":"2026-09-15","effective_date":"2026-09-15","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/news-room/fact-sheets/detail/anxiety-disorders","attachments":[],"summary":"世界卫生组织焦虑障碍实况报道，介绍广泛性焦虑、惊恐障碍、社交焦虑与分离焦虑等类型的表现与患病情况，指出焦虑障碍是最常见的精神障碍之一且常与抑郁共病。报道说明认知行为治疗、选择性5-羟色胺再摄取抑制剂等循证干预的有效性，强调早期识别、减少污名与提高基层服务可及性对减轻疾病负担的关键作用。","tags":["焦虑障碍","常见精神障碍","治疗"],"language":"en"},{"id":"intl-021","title":"Mental health at work","issuer":"World Health Organization","doc_no":"","publish_date":"2026-09-15","effective_date":"2026-09-15","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/news-room/fact-sheets/detail/mental-health-at-work","attachments":[],"summary":"世界卫生组织工作场所心理健康实况报道，说明工作环境中的歧视、过度负荷、职场欺凌与缺乏自主权等心理社会风险对心理健康的影响，同时指出体面工作具有保护作用。报道呼吁雇主落实风险评估、组织干预与个体支持，政府完善职业健康监管，并介绍世卫组织关于工作场所心理健康指南的核心建议。","tags":["职业心理健康","工作场所","预防"],"language":"en"},{"id":"intl-010","title":"Mental health: strengthening our response","issuer":"World Health Organization","doc_no":"","publish_date":"2026-09-11","effective_date":"2026-09-11","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/news-room/fact-sheets/detail/mental-health-strengthening-our-response","attachments":[],"summary":"世界卫生组织心理健康实况报道，界定心理健康为一种健康状态，说明其受生物、社会、心理多重因素影响，并概述焦虑、抑郁等常见问题的全球负担、危险因素与保护因素。报道介绍世卫组织通过政策倡导、mhGAP、自杀预防与去污名化行动推动各国加强心理健康应对，是快速了解国际心理健康概念界定与全球行动框架的基础资料。","tags":["心理健康","实况报道","概念框架"],"language":"en"},{"id":"intl-011","title":"Depression","issuer":"World Health Organization","doc_no":"","publish_date":"2026-09-11","effective_date":"2026-09-11","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/news-room/fact-sheets/detail/depression","attachments":[],"summary":"世界卫生组织抑郁症实况报道，介绍抑郁症的常见症状、病程特点与全球流行情况，指出其是导致残疾的主要原因之一，并列举遗传、生物、心理社会等多重影响因素。报道说明轻中重度抑郁的识别要点、心理治疗与药物治疗的循证选择、自杀风险防范，以及世卫组织推动抑郁症纳入初级卫生保健与减少污名化的相关工作。","tags":["抑郁症","疾病负担","治疗"],"language":"en"},{"id":"intl-013","title":"Mental disorders","issuer":"World Health Organization","doc_no":"","publish_date":"2026-09-11","effective_date":"2026-09-11","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/news-room/fact-sheets/detail/mental-disorders","attachments":[],"summary":"世界卫生组织精神障碍实况报道，概述焦虑障碍、抑郁障碍、双相障碍、精神分裂症等主要类型的流行特征、疾病负担与治疗可及性差距，指出全球大量患者未能获得任何服务。报道强调精神障碍与其他慢性病存在双向影响，呼吁增加投入、发展社区服务、保障患者权利并减少歧视，是了解全球精神障碍流行病学与服务缺口的基础文献。","tags":["精神障碍","流行病学","服务"],"language":"en"},{"id":"intl-014","title":"Schizophrenia","issuer":"World Health Organization","doc_no":"","publish_date":"2026-09-11","effective_date":"2026-09-11","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/news-room/fact-sheets/detail/schizophrenia","attachments":[],"summary":"世界卫生组织精神分裂症实况报道，介绍该病的患病率、发病年龄、阳性与阴性症状、认知损害及对预期寿命的影响，说明其与遗传、环境因素的关联。报道指出抗精神病药物与心理社会康复相结合可有效控制症状并改善功能，强调持续治疗、家庭支持与社区康复的重要性，同时分析患者面临的污名化与人权保障问题。","tags":["精神分裂症","严重精神障碍","治疗"],"language":"en"},{"id":"intl-015","title":"Bipolar disorder","issuer":"World Health Organization","doc_no":"","publish_date":"2026-09-11","effective_date":"2026-09-11","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/news-room/fact-sheets/detail/bipolar-disorder","attachments":[],"summary":"世界卫生组织双相障碍实况报道，介绍躁狂、轻躁狂与抑郁发作的临床表现、首次发病年龄及全球患病率，说明该病自杀风险高、复发率高并常被误诊。报道概述心境稳定剂、心理教育、规律作息与社会支持等综合治疗策略，强调长期维持治疗和早期识别的重要性，呼吁改善服务可及性并减少病耻感。","tags":["双相障碍","心境障碍","治疗"],"language":"en"},{"id":"intl-019","title":"Post-traumatic stress disorder","issuer":"World Health Organization","doc_no":"","publish_date":"2026-09-11","effective_date":"2026-09-11","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/news-room/fact-sheets/detail/post-traumatic-stress-disorder","attachments":[],"summary":"世界卫生组织创伤后应激障碍实况报道，介绍PTSD的再体验、回避、负性认知与高警觉等症状群，说明其发生在经历或目睹严重创伤事件之后，并可能长期影响社会功能。报道概述聚焦创伤的认知行为治疗、眼动脱敏再加工等一线心理干预，强调灾后心理急救、分层照护与避免过早药物化，为突发事件心理援助提供参考。","tags":["创伤后应激障碍","危机干预","创伤"],"language":"en"},{"id":"intl-020","title":"Mental health of older adults","issuer":"World Health Organization","doc_no":"","publish_date":"2026-07-20","effective_date":"2026-07-20","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/news-room/fact-sheets/detail/mental-health-of-older-adults","attachments":[],"summary":"世界卫生组织老年人心理健康实况报道，指出约四分之一老年人受到抑郁、焦虑或痴呆等精神神经障碍影响，介绍丧偶、慢性病、社会隔离、照护压力与虐待等风险因素。报道倡导将心理健康服务融入初级保健与长期照护体系，重视抑郁筛查、痴呆早期识别、社会参与和照护者支持，为积极应对人口老龄化提供政策参考。","tags":["老年人","心理健康","老年痴呆"],"language":"en"},{"id":"intl-017","title":"Autism spectrum disorders","issuer":"World Health Organization","doc_no":"","publish_date":"2025-09-17","effective_date":"2025-09-17","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/news-room/fact-sheets/detail/autism-spectrum-disorders","attachments":[],"summary":"世界卫生组织孤独症谱系障碍实况报道，介绍其社交沟通障碍与重复刻板行为等核心特征、患病率估计及遗传与环境相关因素。报道强调早期识别与行为干预、家长培训、教育融合和全生命周期支持的重要性，指出孤独症人群常共患焦虑抑郁等心理问题，呼吁消除歧视并保障其受教育、就业与社会参与权利。","tags":["孤独症","神经发育障碍","早期干预"],"language":"en"},{"id":"intl-023","title":"Refugee and migrant mental health","issuer":"World Health Organization","doc_no":"","publish_date":"2025-09-01","effective_date":"2025-09-01","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/news-room/fact-sheets/detail/mental-health-and-forced-displacement","attachments":[],"summary":"世界卫生组织难民与移民心理健康实况报道，介绍流离失所人群在迁徙前、途中与安置后经历的暴力、丧失、歧视与不确定处境，及其对抑郁、焦虑、创伤后应激障碍和自杀风险的影响。报道强调提供可及、文化适宜的心理健康与社会心理支持服务，培训基层人员开展心理急救，并保障难民与移民平等获得照护的权利。","tags":["难民","移民","心理健康"],"language":"en"},{"id":"intl-022","title":"Mental health in emergencies","issuer":"World Health Organization","doc_no":"","publish_date":"2025-05-06","effective_date":"2025-05-06","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/news-room/fact-sheets/detail/mental-health-in-emergencies","attachments":[],"summary":"世界卫生组织突发事件中的心理健康实况报道，介绍自然灾害、武装冲突与公共卫生事件对人群心理的短期与长期影响，说明多数人会出现应激反应但可恢复，部分人可能发展为抑郁、PTSD或精神病性障碍。报道倡导分层照护模式、心理急救、社区自助与基本药物保障，强调将心理健康纳入应急准备与响应全过程。","tags":["突发事件","心理急救","危机干预"],"language":"en"},{"id":"intl-008","title":"Clinical descriptions and diagnostic requirements for ICD-11 mental, behavioural and neurodevelopmental disorders (CDDR)","issuer":"World Health Organization","doc_no":"","publish_date":"2024-02-01","effective_date":"2024-02-01","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/publications/i/item/9789240077263","attachments":[],"summary":"世界卫生组织发布的ICD-11精神、行为与神经发育障碍临床描述与诊断要求（CDDR），是ICD-11相应章节的官方诊断手册。文件对各类精神障碍给出定义性特征、边界界定、鉴别诊断、功能影响与编码指引，并反映ICD-11新增的复杂性创伤后应激障碍、游戏障碍等类别。该手册是各国精神科临床诊断、病历书写、流行病学调查与医保编码共同参照的国际标准。","tags":["ICD-11","诊断标准","分类"],"language":"en"},{"id":"intl-028","title":"WHO Mental Health Gap Action Programme (mhGAP)","issuer":"World Health Organization","doc_no":"","publish_date":"2023-11-20","effective_date":"2023-11-20","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/teams/mental-health-and-substance-use/treatment-care/mental-health-gap-action-programme","attachments":[],"summary":"世界卫生组织精神卫生差距行动规划（mhGAP）项目页，介绍该规划自2008年启动以来，通过制定临床指南、培训非专科卫生人员、提供基本药物与支持国家规划，扩大中低收入国家精神卫生服务覆盖的进展。页面汇总mhGAP干预指南、人道主义干预指南、培训工具与国家实施案例，是了解全球基层精神卫生服务能力建设的核心资源。","tags":["mhGAP","服务扩容","基层"],"language":"en"},{"id":"intl-005","title":"Guidelines on mental health at work","issuer":"World Health Organization","doc_no":"","publish_date":"2022-09-28","effective_date":"2022-09-28","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/publications/i/item/9789240053052","attachments":[],"summary":"世界卫生组织2022年发布的首份工作场所心理健康指南，基于系统综述提出组织层面与个体层面的干预建议，包括工作设计、领导力培训、反职场欺凌与骚扰、合理调整岗位、心理社会风险识别与员工支持计划。指南强调用人单位应把心理健康纳入职业健康安全管理体系，为政府、雇主与工会制定职业心理健康政策、开展员工帮助计划提供循证依据。","tags":["职业心理健康","工作场所","劳动者保护"],"language":"en"},{"id":"intl-001","title":"World mental health report: Transforming mental health for all","issuer":"World Health Organization","doc_no":"","publish_date":"2022-06-16","effective_date":"2022-06-16","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/publications/i/item/9789240049338","attachments":[],"summary":"世界卫生组织2022年发布的全球心理健康旗舰报告，系统评估各国心理健康状况、服务缺口与投入水平，指出全球每八人中约有一人存在精神障碍，服务覆盖与质量严重不足。报告提出转变态度、优化服务、加强投入三大转型方向，倡导以社区为基础、以人为本的照护模式，为各国制定心理健康政策与配置资源提供循证依据，是理解全球心理健康治理框架的核心文献。","tags":["全球心理健康","WHO报告","服务体系"],"language":"en"},{"id":"intl-009","title":"Mental Health ATLAS 2020","issuer":"World Health Organization","doc_no":"","publish_date":"2021-10-08","effective_date":"2021-10-08","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/publications/i/item/9789240036703","attachments":[],"summary":"世界卫生组织《2020年精神卫生地图集》对全球171个成员国的精神卫生治理、政策立法、财政投入、人力资源、服务可及性与信息系统进行系统调查。报告显示全球精神卫生人力与财政资源分布极不均衡，中低收入国家服务缺口突出。地图集提供可比较的国别指标，是评估各国精神卫生体系建设进展、制定投入政策与开展国际比较研究的重要数据来源。","tags":["精神卫生地图集","全球监测","资源投入"],"language":"en"},{"id":"intl-027","title":"The State of the World's Children 2021: On My Mind","issuer":"UNICEF","doc_no":"","publish_date":"2021-10-05","effective_date":"2021-10-05","level":"国际指南","region":"联合国","category":"intl","source_site":"www.unicef.org","source_url":"https://www.unicef.org/reports/state-worlds-children-2021","attachments":[],"summary":"联合国儿童基金会《2021年世界儿童状况报告：在心上》，聚焦儿童青少年心理健康，系统分析全球儿童心理问题的流行情况、风险与保护因素，以及家庭、学校、社区与数字环境的影响。报告呼吁加大对儿童心理健康服务的投入，消除污名，将心理健康纳入全民健康覆盖与教育体系，并提出各国可采取的政策与项目建议。","tags":["儿童青少年","心理健康","UNICEF"],"language":"en"},{"id":"intl-002","title":"Comprehensive Mental Health Action Plan 2013-2030","issuer":"World Health Organization","doc_no":"","publish_date":"2021-09-21","effective_date":"2021-09-21","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/publications/i/item/9789240031029","attachments":[],"summary":"世界卫生大会通过的《2013—2030年精神卫生综合行动计划》更新版，为成员国、秘书处及国际伙伴设定清晰行动框架。计划提出四项优先目标：加强有效领导与治理、提供社区综合精神卫生与社会照护服务、实施促进与预防策略、强化信息系统与研究。文件设定到2030年服务覆盖率提升等全球指标，是各国制定国家精神卫生规划、开展心理健康促进行动的国际政策基准。","tags":["精神卫生行动计划","全球目标","治理"],"language":"en"},{"id":"intl-006","title":"LIVE LIFE: An implementation guide for suicide prevention in countries","issuer":"World Health Organization","doc_no":"","publish_date":"2021-06-17","effective_date":"2021-06-17","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/publications/i/item/9789240026629","attachments":[],"summary":"世界卫生组织《LIVE LIFE》国家自杀预防实施指南，围绕限制自杀手段可及性、与媒体互动开展负责任报道、提升青少年社会情感生活技能、早期识别与随访干预等核心策略，给出分阶段落地步骤、监测指标与多部门协作机制。指南强调自杀预防需卫生、教育、司法、媒体与社区共同参与，为各国制定国家自杀预防战略、降低自杀死亡率提供操作框架。","tags":["自杀预防","国家行动","限制手段"],"language":"en"},{"id":"intl-024","title":"Mental health (WHO health topic)","issuer":"World Health Organization","doc_no":"","publish_date":"2019-12-19","effective_date":"2019-12-19","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/health-topics/mental-health","attachments":[],"summary":"世界卫生组织心理健康主题门户页，汇总全球心理健康负担、影响因素、重点行动与相关出版物，介绍世卫组织在政策倡导、服务体系建设、mhGAP推广、自杀预防和去污名化方面的工作。页面提供按主题与出版物分类的资源入口，是检索国际心理健康政策与技术文件、了解全球治理动态的权威起点。","tags":["心理健康","主题页","全球行动"],"language":"en"},{"id":"intl-025","title":"Depression (WHO health topic)","issuer":"World Health Organization","doc_no":"","publish_date":"2019-11-29","effective_date":"2019-11-29","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/health-topics/depression","attachments":[],"summary":"世界卫生组织抑郁症主题页，介绍抑郁症的全球流行状况、疾病负担、症状表现与治疗路径，汇总相关实况报道、指南与出版物。页面强调抑郁症可防可治，倡导将筛查与干预纳入初级卫生保健，减少污名与治疗缺口，为研究者与政策制定者提供权威数据与行动倡议入口。","tags":["抑郁症","主题页","疾病负担"],"language":"en"},{"id":"intl-003","title":"mhGAP Intervention Guide - Version 2.0","issuer":"World Health Organization","doc_no":"","publish_date":"2019-06-24","effective_date":"2019-06-24","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/publications/i/item/9789241549790","attachments":[],"summary":"世界卫生组织精神卫生差距行动规划（mhGAP）干预指南第2版，面向非专科卫生机构与基层医务人员，提供抑郁症、精神病性障碍、双相障碍、癫痫、痴呆、物质使用障碍、自伤自杀、儿童青少年精神障碍等优先疾病的识别、评估与规范化处理流程。指南以简明决策树和药物方案呈现，强调在资源有限地区扩大服务覆盖，是各国基层精神卫生服务能力建设与医务人员培训的核心工具书。","tags":["mhGAP","基层诊疗","非专科机构"],"language":"en"},{"id":"intl-004","title":"mhGAP Humanitarian Intervention Guide (mhGAP-HIG)","issuer":"World Health Organization","doc_no":"","publish_date":"2015-02-28","effective_date":"2015-02-28","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/publications/i/item/9789241548922","attachments":[],"summary":"世界卫生组织《mhGAP人道主义干预指南》，针对自然灾害、武装冲突与流离失所等紧急情境，指导非专科卫生人员在缺乏精神卫生专科资源的条件下识别和处理急性应激反应、创伤后应激障碍、抑郁、精神病性障碍及自伤自杀风险。指南强调心理急救、基本药物保障与转诊协作，是应急心理援助、灾后心理危机干预与国际人道救援工作的重要技术规范。","tags":["人道主义应急","危机干预","mhGAP"],"language":"en"},{"id":"intl-026","title":"Goal 3: Good Health and Well-being","issuer":"United Nations","doc_no":"","publish_date":"2015-01-07","effective_date":"2015-01-07","level":"国际指南","region":"联合国","category":"intl","source_site":"www.un.org","source_url":"https://www.un.org/sustainabledevelopment/health/","attachments":[],"summary":"联合国可持续发展目标第三项“良好健康与福祉”官方页面，列出到2030年降低非传染性疾病过早死亡率、促进心理健康与福祉、加强物质滥用防治等具体目标，其中目标3.4明确要求通过预防和治疗减少非传染性疾病导致的过早死亡并促进心理健康。页面提供指标、进展报告与相关行动倡议，是国际心理健康政策的上位框架。","tags":["可持续发展目标","SDG3","健康"],"language":"en"},{"id":"intl-007","title":"WHO guidelines on conditions specifically related to stress","issuer":"World Health Organization","doc_no":"","publish_date":"2013-03-17","effective_date":"2013-03-17","level":"国际指南","region":"WHO","category":"intl","source_site":"www.who.int","source_url":"https://www.who.int/publications/i/item/9789241505406","attachments":[],"summary":"世界卫生组织关于应激相关障碍的循证指南，聚焦急性应激反应、创伤后应激障碍与丧亲哀伤等状况，评估心理急救、认知行为干预、眼动脱敏再加工及药物干预的证据强度，并提出在初级卫生保健与社区环境中开展分层照护的建议。指南为突发事件心理援助、灾后心理重建与基层创伤干预提供标准化技术参考，强调避免不必要的医学化与药物滥用。","tags":["应激相关障碍","心理急救","创伤"],"language":"en"},{"id":"foreign-008","title":"Mental Health and Wellbeing Act 2022 (Victoria)","issuer":"Parliament of Victoria, Australia","doc_no":"Act No. 33 of 2022","publish_date":"2022-09-06","effective_date":"2023-12-01","level":"他国法律","region":"澳大利亚","category":"foreign","source_site":"www.legislation.vic.gov.au","source_url":"https://www.legislation.vic.gov.au/in-force/acts/mental-health-and-wellbeing-act-2022/010","attachments":[],"summary":"澳大利亚维多利亚州2022年《精神健康与福祉法》，回应皇家委员会对精神卫生系统的调查建议，以患者权利、自主与康复为导向，规定自愿治疗优先、最少限制原则、知情同意与预立指示，设立精神健康与福祉委员会及区域委员会，强化家庭与照护者参与。该法代表澳大利亚精神卫生立法从医疗模式向人权与社区融合模式的转型。","tags":["澳大利亚","维州","精神卫生改革"],"language":"en"},{"id":"foreign-002","title":"SUPPORT for Patients and Communities Act","issuer":"United States Congress","doc_no":"Public Law 115-271","publish_date":"2018-10-24","effective_date":"2018-10-24","level":"他国法律","region":"美国","category":"foreign","source_site":"www.govinfo.gov","source_url":"https://www.govinfo.gov/content/pkg/PLAW-115publ271/html/PLAW-115publ271.htm","attachments":[],"summary":"美国2018年通过的《支持患者与社区法案》，针对阿片类药物滥用危机，扩大成瘾治疗与康复支持、医疗补助覆盖范围和处方药监测，并加强围产期妇女、青少年与农村地区的行为健康服务。法案包含多项精神健康条款，推动物质使用障碍与精神疾病协同治疗、远程医疗应用及康复住房建设，是美国行为健康政策的重要组成。","tags":["美国","阿片危机","物质使用障碍"],"language":"en"},{"id":"foreign-016","title":"Mental Healthcare Act, 2017 (India)","issuer":"Parliament of India","doc_no":"Act No. 10 of 2017","publish_date":"2017-04-07","effective_date":"2018-05-29","level":"他国法律","region":"印度","category":"foreign","source_site":"legislative.gov.in","source_url":"https://legislative.gov.in/actsofparliamentfromtheyear/mental-healthcare-act-2017","attachments":[],"summary":"印度《2017年精神卫生保健法》取代1987年旧法，以权利为本，规定精神障碍者享有尊严、隐私、知情同意与社区生活权利，引入预立指示与指定代表制度，规范自愿、辅助与非自愿入院程序，设立中央与邦精神卫生机构及审查委员会，并将自杀未遂去罪化。该法要求政府提供可及的精神卫生服务，是南亚地区精神卫生立法的重要范本。","tags":["印度","精神卫生权利","预立指示"],"language":"en"},{"id":"foreign-001","title":"21st Century Cures Act","issuer":"United States Congress","doc_no":"Public Law 114-255","publish_date":"2016-12-13","effective_date":"2016-12-13","level":"他国法律","region":"美国","category":"foreign","source_site":"www.govinfo.gov","source_url":"https://www.govinfo.gov/content/pkg/PLAW-114publ255/html/PLAW-114publ255.htm","attachments":[],"summary":"美国2016年颁布的《21世纪治愈法案》，是近年来美国最重要的卫生立法之一。法案设立“帮助家庭应对精神疾病”专项，要求整合行为健康与初级保健、加强严重精神疾病服务、扩大精神健康队伍、推动电子健康记录与隐私规则改革，并投入巨资支持脑科学研究与阿片危机应对，对美国精神卫生服务体系与心理健康循证实践产生深远影响。","tags":["美国","精神健康改革","联邦立法"],"language":"en"},{"id":"foreign-009","title":"Mental Health Act 2016 (Queensland)","issuer":"Parliament of Queensland, Australia","doc_no":"Act No. 5 of 2016","publish_date":"2016","effective_date":"2017-03-05","level":"他国法律","region":"澳大利亚","category":"foreign","source_site":"www.legislation.qld.gov.au","source_url":"https://www.legislation.qld.gov.au/view/html/inforce/current/act-2016-005","attachments":[],"summary":"澳大利亚昆士兰州《2016年精神健康法》，规定精神健康评估、非自愿治疗标准与审查程序，强调最少限制原则、患者参与决策、预先声明与独立患者访视员制度，并设立精神健康法庭。该法将“精神疾病”定义聚焦于临床意义的功能损害，注重减少污名与保障原住民文化安全，是昆士兰州精神卫生服务的主要法律依据。","tags":["澳大利亚","昆士兰","非自愿治疗"],"language":"en"},{"id":"foreign-003","title":"Paul Wellstone and Pete Domenici Mental Health Parity and Addiction Equity Act of 2008","issuer":"United States Congress","doc_no":"Public Law 110-343","publish_date":"2008-10-03","effective_date":"2010-01-01","level":"他国法律","region":"美国","category":"foreign","source_site":"www.govinfo.gov","source_url":"https://www.govinfo.gov/content/pkg/PLAW-110publ343/html/PLAW-110publ343.htm","attachments":[],"summary":"美国2008年《精神健康平等与成瘾公平法案》，要求团体健康保险在精神健康与物质使用障碍福利的赔付限额、共付比例、网络覆盖等方面，与医疗外科福利保持同等水平，禁止设置更严格的限制。该法是美国心理健康保险公平的核心法律，显著改善精神障碍患者的经济可及性，并为后续执法与州级立法提供基础。","tags":["美国","医保公平","精神健康"],"language":"en"},{"id":"foreign-012","title":"Mental Health (Care and Treatment) Act 2008","issuer":"Parliament of Singapore","doc_no":"Act 21 of 2008","publish_date":"2008","effective_date":"2008-09-15","level":"他国法律","region":"新加坡","category":"foreign","source_site":"sso.agc.gov.sg","source_url":"https://sso.agc.gov.sg/Act/MHCTA2008","attachments":[],"summary":"新加坡《2008年精神健康（照护与治疗）法》，规定精神障碍者的自愿与非自愿收治程序、精神科评估与治疗同意规则，授权警方与医护人员处置存在风险的患者，并强调在社区中提供照护与康复服务。该法替代原有的精神科收治规定，体现从机构收容向社区照护与权利保障并重的转变，是新加坡精神卫生服务的主要法律依据。","tags":["新加坡","精神卫生","非自愿收治"],"language":"en"},{"id":"foreign-007","title":"Mental Health Care Act 17 of 2002","issuer":" Parliament of the Republic of South Africa","doc_no":"Act No. 17 of 2002","publish_date":"2002-10-28","effective_date":"2004-12-15","level":"他国法律","region":"南非","category":"foreign","source_site":"www.gov.za","source_url":"https://www.gov.za/documents/mental-health-care-act","attachments":[],"summary":"南非2002年《精神卫生照护法》，取代旧的精神卫生立法，确立以人权为基础的精神卫生服务框架，规定精神障碍者的照护、治疗与康复权利，设立精神卫生审查委员会，规范自愿、辅助与非自愿入院程序及期限，强化社区服务与初级卫生保健整合。该法强调尊重患者尊严与自主，是非洲地区精神卫生法律改革的代表性文本。","tags":["南非","精神卫生照护","人权"],"language":"en"},{"id":"foreign-013","title":"Mental Health Act 2001 (Ireland)","issuer":"Oireachtas (Parliament of Ireland)","doc_no":"Act No. 25 of 2001","publish_date":"2001-07-10","effective_date":"2001-07-10","level":"他国法律","region":"爱尔兰","category":"foreign","source_site":"www.irishstatutebook.ie","source_url":"https://www.irishstatutebook.ie/eli/2001/act/25/enacted/en/html","attachments":[],"summary":"爱尔兰《2001年精神健康法》，规定精神障碍者的非自愿入院与治疗程序、独立审查机制与精神健康法庭（Mental Health Tribunal）制度，设立精神健康委员会监督服务质量与患者权利，强调知情同意、预立医疗指示与最少限制原则。该法推动爱尔兰精神卫生服务从机构化向社区化转型，并为后续修订与 capacity 立法奠定基础。","tags":["爱尔兰","精神卫生","权利审查"],"language":"en"},{"id":"foreign-006","title":"Lei nº 10.216, de 6 de abril de 2001","issuer":"Congresso Nacional do Brasil","doc_no":"Lei 10.216/2001","publish_date":"2001-04-06","effective_date":"2001-04-06","level":"他国法律","region":"巴西","category":"foreign","source_site":"www.planalto.gov.br","source_url":"https://www.planalto.gov.br/ccivil_03/leis/leis_2001/l10216.htm","attachments":[],"summary":"巴西2001年《精神卫生法》（第10.216号法律），确立精神障碍者权利保护与去机构化原则，规定精神障碍患者应优先在社区网络中获得照护，限制长期住院，保障自愿入院与知情同意，禁止歧视并保护患者的社会参与和劳动权利。该法推动巴西以社区精神卫生中心（CAPS）为核心重构服务体系，是拉美地区精神卫生人权改革的标志性立法。","tags":["巴西","精神卫生改革","去机构化"],"language":"en"},{"id":"foreign-015","title":"Lov om psykisk helsevern (Mental Health Care Act)","issuer":"Stortinget (Parliament of Norway)","doc_no":"LOV-1999-07-02-62","publish_date":"1999-07-02","effective_date":"2001-01-01","level":"他国法律","region":"挪威","category":"foreign","source_site":"lovdata.no","source_url":"https://lovdata.no/dokument/NL/lov/1999-07-02-62","attachments":[],"summary":"挪威《精神卫生照护法》，规范精神障碍者的检查、自愿与非自愿住院、治疗及权利保障，规定非自愿治疗须满足严重精神障碍、存在明显风险且自愿治疗无效等条件，并由独立监督委员会审查。法律强调患者参与、治疗计划、最少限制与社区服务优先，是挪威精神卫生服务体系与患者权利保护的核心立法。","tags":["挪威","精神卫生照护","非自愿治疗"],"language":"en"},{"id":"foreign-011","title":"Mental Health Act, R.S.B.C. 1996, c. 288 (British Columbia)","issuer":"Legislative Assembly of British Columbia, Canada","doc_no":"R.S.B.C. 1996, c. 288","publish_date":"1996","effective_date":"1996","level":"他国法律","region":"加拿大","category":"foreign","source_site":"www.bclaws.gov.bc.ca","source_url":"https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/96288_01","attachments":[],"summary":"加拿大不列颠哥伦比亚省《精神健康法》，规定精神障碍者的入院评估、非自愿留院、治疗同意与权利保障程序，设立精神健康审查委员会受理复议，明确警察协助、患者财产管理与社区照护安排。该法是不列颠哥伦比亚省开展精神科急诊、危机响应与社区治疗的基础性法律，强调在保障安全的同时尊重患者尊严与程序正义。","tags":["加拿大","不列颠哥伦比亚省","精神卫生"],"language":"en"},{"id":"foreign-005","title":"障害者基本法","issuer":"日本国会","doc_no":"平成5年法律第84号","publish_date":"1993-12-03","effective_date":"1993-12-03","level":"他国法律","region":"日本","category":"foreign","source_site":"laws.e-gov.go.jp","source_url":"https://laws.e-gov.go.jp/law/322AC0000000084","attachments":[],"summary":"日本《残障者基本法》，规定国家与地方公共团体在残障者自立与社会参与方面的责任，禁止基于残障的歧视，要求制定残障者基本计划，推进教育、就业、医疗、福祉与无障碍环境建设。2011年修订后引入“合理便利”理念，将精神障碍、发育障碍等纳入保护范围，是日本精神障碍者权利保障与去机构化政策的上位法依据。","tags":["日本","残障权利","反歧视"],"language":"en"},{"id":"foreign-010","title":"Mental Health Act, R.S.O. 1990, c. M.7 (Ontario)","issuer":"Legislative Assembly of Ontario, Canada","doc_no":"R.S.O. 1990, c. M.7","publish_date":"1990-12-31","effective_date":"1990-12-31","level":"他国法律","region":"加拿大","category":"foreign","source_site":"www.ontario.ca","source_url":"https://www.ontario.ca/laws/statute/90m07","attachments":[],"summary":"加拿大安大略省《精神健康法》，规定精神障碍者的自愿与非自愿住院、精神科评估、同意治疗与社区治疗令等制度，明确医生、治安官与法院的职责及患者权利，包括聘请律师、申请复议与同意治疗的能力评估。该法是安省精神卫生服务与危机干预的核心法律，经多次修订以平衡公共安全与患者自主权。","tags":["加拿大","安大略省","非自愿住院"],"language":"en"},{"id":"foreign-014","title":"Legge 13 maggio 1978, n. 180","issuer":"Parlamento Italiano","doc_no":"Legge 180/1978","publish_date":"1978-05-13","effective_date":"1978-05-18","level":"他国法律","region":"意大利","category":"foreign","source_site":"www.gazzettaufficiale.it","source_url":"https://www.gazzettaufficiale.it/eli/id/1978/05/18/078U0180/sg","attachments":[],"summary":"意大利1978年第180号法律（又称“巴西利亚法”），废除精神病院，规定精神障碍者应在社区中接受自愿治疗，非自愿治疗须经公共卫生部门提议、两名医生诊断并由市长批准，且应在综合医院精神科或社区服务机构短期实施。该法开创全球去机构化先例，确立精神卫生服务以社区为中心、尊重人身自由的原则，影响多国改革。","tags":["意大利","去机构化","巴西利亚法"],"language":"en"},{"id":"foreign-004","title":"精神保健及び精神障害者福祉に関する法律","issuer":"日本国会","doc_no":"昭和25年法律第123号","publish_date":"1950-05-01","effective_date":"1950-05-01","level":"他国法律","region":"日本","category":"foreign","source_site":"laws.e-gov.go.jp","source_url":"https://laws.e-gov.go.jp/law/325AC0000000123","attachments":[],"summary":"日本《精神保健及精神障碍者福祉法》，是日本精神卫生领域的基础法律。法律确立精神障碍者的人权保障与社区生活支援理念，规定精神保健指定医制度、非自愿住院（措置入院、医疗保护住院）的程序与审查机制，设立精神医疗审查会，并规范精神保健福祉中心、市町村精神保健服务与自立支援医疗。该法经多次修订，体现从收容医疗向社区融合的转型。","tags":["日本","精神保健","非自愿住院"],"language":"en"}];
